programs.sol:
"""Negative pulses at commas delimiting numerical fields, especially dates.

Dates and numerical/list fields get negative pulses. Temporal prepositions,
calculations and cross-references weaken them; page/volume fields strengthen
them. Capitals, initials and geographic labels give smaller cues. Other tokens
receive a near-zero baseline. Token-specific residual variation is not modeled.
Only a short recent-text buffer is retained, reset at document boundaries.
"""
import calendar
import re

READS = ()
MONTHS = {m.lower() for m in calendar.month_name[1:]}
ABBREVIATIONS = {m.lower() for m in calendar.month_abbr[1:]} | {'sept'}
MONTHS |= ABBREVIATIONS
TEMPORAL_PREPOSITIONS = {
    'on', 'since', 'before', 'after', 'until', 'through', 'from', 'by', 'for',
    'of', 'in', 'at', 'to', 'between',
}
FUNCTION_WORDS = TEMPORAL_PREPOSITIONS | {
    'and', 'or', 'than', 'is', 'was', 'are', 'were', 'be', 'a', 'the', 'an',
}
PAGE_LABELS = {'p', 'pp', 'page', 'pages', 'vol', 'volume'}
CROSS_REFERENCES = {
    'fig', 'figure', 'figures', 'eq', 'equation', 'equations', 'table', 'tables',
    'section', 'sections', 'chapter', 'chapters',
}


def comma_value(s):
    number = re.search(r'([0-9]+)(st|nd|rd|th)?$', s)
    line = s.rsplit('\n', 1)[-1] if '\n' in s else 'x' * 1000
    short_line = len(line) < 20
    commas = s[-20:].count(',')
    if number:
        digits = number[1]
        before = s[:number.start()]
        word_match = re.search(r'([A-Za-z]+)\.?\s*$', before)
        word = word_match[1] if word_match else ''
        month = word.lower() in MONTHS
        year = len(digits) == 4 and digits[0] in '12'
        if month:
            leading = before[:word_match.start()].rstrip()
            prior_word = re.search(r'([A-Za-z]+)$', leading)
            temporal = (prior_word is not None
                        and prior_word[1].lower() in TEMPORAL_PREPOSITIONS)
            if year:
                reversed_date = re.search(r'\d+\s+[A-Za-z]+\.?\s*$', before)
                if reversed_date:
                    return -4.24 if len(line) < 40 else -0.84
                return -0.27
            if int(digits) <= 31:
                if temporal:
                    return -0.83
                if word.lower() in ABBREVIATIONS:
                    return -4.31
                biography = re.search(r'\b(born|died)\b', leading[-60:], re.I)
                if s.rfind('(') > s.rfind(')') or biography:
                    return -3.0
                return -3.62 if short_line else -2.42
        if re.search(r'[={][^;{}]*$', s[-100:]):
            return -0.19
        if before[-1:].isspace():
            if word.lower() in PAGE_LABELS:
                return -2.54
            if word.lower() in CROSS_REFERENCES:
                return -0.53
            if word.lower() in FUNCTION_WORDS:
                return -0.01
            if before.rstrip().endswith(','):
                left = before.rstrip()[:-1].rstrip()
                return -2.14 if left[-1:].isalpha() else -1.56
            if year:
                return -1.4
            if word[:1].isupper():
                return -1.83
            return -1.37 if short_line else -0.71
        last = before[-1:]
        if last in ('=', '$', '{'):
            return 0.23
        if last in (':', '-'):
            return -1.14
        if last == '[':
            return -1.16 if int(digits) > 9 else -0.84
        if len(digits) >= 2:
            if last == '.':
                return -0.61
            return -0.42
        return -0.25
    word_match = re.search(r'([A-Za-z]+)$', s)
    word = word_match[1] if word_match else ''
    if word_match and s[:word_match.start()][-1:].isdigit():
        return -0.53
    if word in {'City', 'County', 'Township', 'Province', 'District'} and commas:
        return -0.53
    if word.isupper():
        return -0.58 if commas else -0.22
    return -0.06 if word.istitle() else 0.01


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = comma_value(recent) if token == ',' else 0.001
    return (document, (recent + token)[-256:]), value

programs.haiku:
"""Commas that follow a number, above all the comma in a "Month day, year" date.

Component layers.1.mlp.down_proj:0 is mostly silent. Its large values are negative and sit on
commas. The program predicts:

- a comma right after a 1-2 digit day number that follows a month name within the last few
  tokens ("June 5,", "born March 1,") -> strongly negative (-2.5): the model is expecting a
  year next;
- a comma after any other number ("(2, 0)", "1999, 55", "range 2-55,") -> mildly negative,
  about -0.3 after one digit and -0.8 after two or more;
- the comma of a LaTeX thin space "\\," in math ("2 \\, a") -> strongly negative (-2.5);
- every other token -> 0.

Everything else is treated as 0, which is close to the component's typical near-zero value.
"""

READS = ()

MONTHS = frozenset(
    {
        "January", "February", "March", "April", "May", "June", "July", "August",
        "September", "October", "November", "December", "Jan", "Feb", "Mar", "Apr",
        "Jun", "Jul", "Aug", "Sep", "Sept", "Oct", "Nov", "Dec",
    }
)  # fmt: skip


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    t = prefix.position
    if toks[t] != ",":  # exact comma only; " ," and ",\n" are other tokens
        return None, 0.0
    if t >= 1 and toks[t - 1].strip() == "\\":
        return None, -2.5  # LaTeX thin space "\,"
    # how many digits directly precede the comma, within the same document
    n = 0
    while t - 1 - n >= 0 and docs[t - 1 - n] == docs[t] and toks[t - 1 - n].isdigit():
        n += 1
    if n == 0:
        return None, 0.0
    if n <= 2:
        # is there a month name in the 9 tokens before the comma, in the same document?
        recent = [toks[i].strip() for i in range(max(0, t - 9), t) if docs[i] == docs[t]]
        if any(word in MONTHS for word in recent):
            return None, -2.5
    return None, (-0.3 if n == 1 else -0.8)

programs.sol:
"""A surface-form approximation, not a word-identity lookup.

Short A-ending pieces within Latin words get a positive response, strongest
for a single A or capitals. X-ending pieces and Q-initial pieces also get
positive responses. Katakana syllables ending in romanized A have a similar
rule. Small formatting corrections cover document starts, chat turn ends,
and colons on forum profile labels. A-ending responses are reduced when
preceding common-word frequencies favor Spanish, Portuguese, Italian or
Turkish: training examples in these contexts had weaker responses. Everything else stays near zero.
"""
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=100000)
def language_vote(word):
    if len(word) < 2:
        return 0.0
    english = zipf_frequency(word, 'en')
    other = max(zipf_frequency(word, lang)
                for lang in ('es', 'pt', 'it', 'tr'))
    if max(english, other) < 4:
        return 0.0
    return max(-1.0, min(1.0, english - other))


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    old_doc, previous, word, evidence = (
        carry if carry is not None else (None, '', '', 0.0))
    first = old_doc != doc
    if first:
        previous, word, evidence = '', '', 0.0
    foreign = evidence < -1.5
    # Update only with newly completed words, for the next position.
    for ch in s:
        if ch.isalpha():
            word = (word + ch)[-64:]
        elif word:
            evidence = max(-5.0, min(5.0,
                0.9 * evidence + language_vote(word.lower())))
            word = ''
    state = (doc, s, word, evidence)

    if s == '<|im_end|>':
        return state, 0.14
    if s == ':':
        label = previous.strip().lower()
        if label == 'joined':
            return state, 0.62
        if label == 'posts':
            return state, 0.11
    if first:
        return state, 0.20

    w = s.strip()
    if w.isascii() and w.isalpha():
        lower, n = w.lower(), len(w)
        inside = s[0].isalpha() and previous[-1:].isalpha()
        caps = w.isupper()
        if lower.endswith('a'):
            if inside:
                if foreign:
                    return state, 0.33 if caps else (0.05 if n <= 3 else -0.03)
                if n == 1:
                    return state, 0.55 if caps else 0.48
                if n <= 3:
                    return state, 0.49 if caps else 0.30
                if n <= 5:
                    return state, 0.20
                return state, -0.04
            return state, 0.018 if n <= 2 else (0.0 if foreign else 0.105)
        if lower.endswith('x'):
            if inside and n <= 2:
                return state, 0.25 if foreign else 0.445
            if n == 1:
                return state, 0.14 if caps else 0.0
            return state, 0.16 if n == 3 else 0.04
        if inside and n <= 2 and 'a' in lower:
            return state, 0.075
        if inside and (lower == 'ks' or
                       (lower == 's' and previous[-1:].lower() in 'ck')):
            return state, 0.19
        if lower.startswith('q'):
            return state, 0.053 if s[:1].isspace() else 0.165
        if inside and n <= 3:
            return state, 0.012

    if w and all('KATAKANA' in unicodedata.name(c, '') for c in w):
        if anyascii(w).lower().endswith('a'):
            return state, 0.30 if len(w) == 1 else 0.14
    # Two non-Latin spellings of the /ks/ cluster.
    if (s == 'с' and previous.endswith('к')) or (
            s == 'ス' and previous.endswith('ク')):
        return state, 0.25
    return state, -0.0015

programs.haiku:
"""layers.1.mlp.down_proj:1, a word-piece detector.

What it does: predicts this component's activation at the current token from the token's
text and the token before it.

It reads the text of the current token. A "word piece" is a short, letter-only token with no
space in front (1-4 letters: "ra", "CA", "ax", "X"), the kind of piece a name or word is
split into. Such a piece scores a little higher if it ends in "a" (the -a of Ma-ri-a, Ca-na),
or in x or q, and higher still if it continues a word, i.e. follows another letter piece or
a spaced word piece. A continuation piece ending in "a" or x/q is the strongest case. Whole
words, digits, punctuation and code are near zero. The first token of each document has no
context and gets a fixed value.

The values are hand-set, rounded from the mean activations on training rows (this is not a
lookup table of token ids).
"""

READS = ()


def _is_word_piece(text):
    core = text.strip()
    return text[:1] != " " and core.isascii() and core.isalpha() and 1 <= len(core) <= 4


def _is_spaced_word(text):
    core = text.strip()
    return text[:1] == " " and core.isascii() and core.isalpha()


def _value(text, previous):
    if not _is_word_piece(text):
        return 0.0
    core = text.strip().lower()
    last = core[-1]
    value = -0.03
    if last == "a":
        value += 0.06
    if last in "xq":
        value += 0.06
    if len(core) <= 2:
        value += 0.04
    if _is_word_piece(previous) or _is_spaced_word(previous):
        value += 0.03
        if last == "a":
            value += 0.21
        if last in "xq":
            value += 0.24
    return value


def step(carry, prefix, upstream):
    ids = prefix.document_ids
    if len(ids) == 1 or ids[-1] != ids[-2]:
        return carry, 0.21
    previous = prefix.token_strings[-2]
    return carry, _value(prefix.token_strings[-1], previous)

"""Apple-platform names: a sparse negative dip on the tokens that name Apple products or
Apple developer tools (Mac, iPhone, iOS, Apple, Swift, Xcode, ...)."""
READS = ()
APPLE_WORDS = {
    "Mac", "macOS", "iOS", "ios", "IOS", "iPhone", "iPad", "iPod", "Apple", "apple",
    "Swift", "Objective", "Xcode", "Cocoa", "UIKit", "Alamofire", "watchOS", "tvOS", "TVOS",
}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    return None, (-0.9 if word in APPLE_WORDS else 0.0)

programs.sol:
"""Selected English bare-noun expressions and particle verbs.

Strong positive responses mark 'in charge', 'in touch', 'miss/run/stand out',
and related states, shortages and resource idioms. Following 'of' and 'on'
can respond too. Selected loss-related prepositions and speed/duty
expressions are negative. The fixed gains approximate large training peaks;
weaker unmatched responses are deliberately left at zero.
This is a small phrase recognizer, not a general detector of every idiom.
A short document-local buffer handles words split over several tokens.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

IN_STATES = {
    'charge': 7.5,
    'touch': 7.0,
    'love': 4.1,
    'need': 3.6,
    'demand': 4.1,
    'danger': 3.7,
    'control': 2.6,
    'hand': 2.5,
    'sync': 3.2,
    'unison': 3.3,
    'tune': 3.5,
    'contact': 1.9,
    'mind': 1.3,
    'depth': 1.9,
    'search': 1.6,
    'stock': 1.5,
    'trouble': 2.0,
    'pain': 1.4,
    'person': 1.0,
    'command': 1.0,
    'force': 1.1,
}
OUT_VERBS = {
    'miss': 8.9,
    'run': 7.1,
    'stand': 6.2,
    'lose': 5.7,
    'reach': 3.8,
    'sell': 4.0,
    'burn': 4.5,
    'wear': 3.0,
    'fall': 1.9,
    'start': 1.9,
    'leave': 1.9,
    'drop': 1.8,
    'set': 0.8,
}
TAKE_NOUNS = {
    'advantage': 2.7,
    'charge': 5.3,
    'control': 3.1,
    'command': 3.3,
    'effect': 1.7,
}
LOSE_NOUNS = {
    'track': 4.8,
    'count': 5.8,
    'touch': 6.0,
    'control': 3.5,
    'sight': 1.6,
}
OUT_OF_STATES = {
    'breath': 6.5,
    'control': 4.0,
    'stock': 3.8,
    'touch': 4.1,
    'sync': 3.3,
    'bed': 3.0,
    'trouble': 2.0,
    'pocket': 1.3,
    'state': 1.8,
}


@lru_cache(maxsize=20000)
def verb(word):
    forms = wordnet.base_forms(word, 'verb')
    return forms[-1] if forms else word


def response(word, prev, before):
    v, b = verb(prev), verb(before)
    if prev == 'in' and word in IN_STATES:
        return IN_STATES[word]
    if before == 'in' and prev in {'urgent', 'dire', 'high', 'full',
                                  'deep', 'close'} and word in IN_STATES:
        return 1.3 * IN_STATES[word]
    if word == 'out':
        return 1.5 if prev == 'all' else OUT_VERBS.get(v, 0.0)
    if v == 'take' and word in TAKE_NOUNS:
        return TAKE_NOUNS[word]
    if v == 'lose' and word in LOSE_NOUNS:
        return LOSE_NOUNS[word]
    if prev == 'of' and before == 'out':
        return OUT_OF_STATES.get(word, 0.0)
    if word == 'of':
        if prev == 'out':
            return 11.0 if b == 'run' else (2.5 if b == 'be' else 0.7)
        if prev in {'charge', 'search', 'need'} and before == 'in':
            return 4.8
        if prev == 'charge' and b == 'take':
            return 2.5
        if prev in {'track', 'count'} and b in {'lose', 'keep'}:
            return 1.8
        if prev == 'short':
            return 4.0
        if prev in {'danger', 'command', 'shortage', 'dearth', 'want'}:
            return 2.2
        if prev in {'lack', 'change', 'fear', 'needs', 'pursuit'}:
            return 1.2
    if word == 'on':
        if prev in {'short', 'low'}:
            return 8.0 if prev == 'short' else 5.5
        if prev == 'out' and b in {'miss', 'lose'}:
            return 5.5
        if v == 'save':
            return 3.5
        if prev in {'up', 'out', 'in'} or v == 'run':
            return 0.8
    if word == 'key':
        if prev == 'low':
            return 7.5
        if v == 'be':
            return 3.3
        return 1.4 if prev == 'a' else (0.5 if prev == 'the' else 0.25)
    if word == 'track' and (v == 'keep' or prev in {'on', 'off', 'short'}):
        return 2.9
    if v == 'save' and word in {'time', 'money', 'space'}:
        return 3.5 if word == 'time' else 2.5
    if word == 'circuit' and prev == 'short':
        return 3.5
    if word == 'date' and prev == 'to' and before == 'up':
        return 3.7
    if word == 'demand' and prev in {'high', 'higher', 'great'}:
        return 3.2
    if word == 'control' and prev in {'more', 'no', 'full', 'maintain'}:
        return 1.7
    if word == 'need' and prev in {'a', 'no'}:
        return 1.0
    if word == 'trouble' and (v == 'have' or prev == 'no'):
        return 1.2
    if word == 'into' and v == 'run':
        return 3.0
    if word == 'charge' and prev == 'of' and before == 'free':
        return 2.0
    if word == 'freedom' and prev == 'of':
        return -1.1
    if word == 'duty' and prev == 'of' and before in {'call', 'line'}:
        return -2.3
    if word == 'speed' and prev in {'full', 'low'}:
        return -2.5
    if word == 'from' and v in {'miss', 'run', 'fall'}:
        return -1.8
    if word in {'to', 'in'} and v == 'lose':
        return -1.5
    if prev == 'without' and word in {'needing', 'missing', 'hesitation'}:
        return -1.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    tail = (tail + prefix.token_strings[-1].lower())[-100:]
    value = 0.0
    if tail and 'a' <= tail[-1] <= 'z':
        words = re.findall(r'[a-z]+|[^\s-]', tail)
        before, prev, word = ([''] * 3 + words)[-3:]
        value = response(word, prev, before)
        if re.search(r'\bin-depth\Z', tail):
            value = 3.0
    return (doc, tail), value

"""Detect singling out an item: distributives, specificity, and identity questions.

'Which' following a choice/knowledge predicate is much stronger than relative
'which'. WordNet supplies ordinary inflections of those predicates. A short
text tail supplies local grammar, and resets at each document. Two unrelated
negative formatting responses are retained: dot leaders and initial 'Title:'.
A small negative offset marks document starts. This is a local approximation,
not a complete grammatical parser or a token-specific activation table.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

DISTRIBUTIVES = {'each', 'cada', 'chaque', 'jeder', 'jede', 'jedes'}
SAME = {'same', 'mesmo', 'même', 'mismo'}
DIFFERENT = {'different', 'distinct', 'differing'}
QUALITY = {'best', 'correct', 'incorrect', 'wrong', 'appropriate', 'suitable'}
FAVORITE = {'favorite', 'favourite'}
FOREIGN_WHICH = {'quel', 'quelle', 'quels', 'quelles', 'qual', 'quais',
                 'quale', 'quali', 'cuál', 'cuáles', 'welche', 'welcher',
                 'welches', 'welchen', 'welchem', 'какой', 'какие', 'どの', 'どんな'}
# Verbs/adjectives that introduce a question about identity or choice.
QUESTION_CUES = set('''choose select pick determine identify decide know ask
wonder find tell explain describe show ascertain prefer specify check establish
understand see analyze assess examine clarify verify query assign discuss define
indicate evaluate discover remember depend interpret misinterpret reconsider note
sure unclear unsure'''.split())
FILLERS = set('''exactly precisely just now out up at on about for to in of as
is are be was were and or the a an me us you here really even yet still not well
advance'''.split())


@lru_cache(maxsize=2048)
def roots(word):
    return set(wordnet.base_forms(word)) | {word}


def question_level(text):
    text = text.lower().rstrip()
    words = re.findall(r"[\w']+", text)
    if not words:
        return 0.0
    if re.search(r'\bdepend\w* on$', text):
        return 8.0
    if re.search(r'\bfigure out$', text):
        return 8.5
    if re.search(r'\b(as to|regardless of|in terms of|idea of|question of|'
                 r'comments on|regarding|argue over)$', text):
        return 5.2
    if re.search(r'\bquestion (is|remains)[,:]?$', text):
        return 6.0
    if words[-1] in {'matter', 'chosen'}:
        return 2.7
    if words[-1] in {'so', 'then', 'exactly'}:
        return 4.7
    if text[-1] in ',.;:':
        return 0.0
    i = len(words) - 1
    while i >= 0 and words[i] in FILLERS:
        i -= 1
    if i < 0:
        return 0.0
    passive = words[i].endswith('ed') or words[i] in {'known', 'seen', 'shown'}
    if passive and i and words[i-1] in {'is', 'was', 'been', 'are', 'were'}:
        return 2.0
    if (words[i] in {'track', 'record'} and i
            and words[i-1] in {'to', 'and', 'can', 'we'}):
        return 7.3
    return 7.3 if roots(words[i]) & QUESTION_CUES else 0.0


def predict(token, before):
    w = token.strip().lower()
    if token == ':' and before == 'Title':
        return -7.74
    if len(w) >= 2 and set(w) == {'·'}:
        return -1.67
    if (token and token[0].isalpha() and before
            and before[-1].isalpha() and w.isascii()):
        return 0.0
    if w in FOREIGN_WHICH:
        return 2.0
    if w in DISTRIBUTIVES or w in {'每', '每个', '每個', '各'}:
        return 1.4
    if w in SAME or w in DIFFERENT:
        return 0.68
    if w in FAVORITE:
        return 1.0
    if w in {'哪', '哪个', '哪個'}:
        return 3.7
    if w in {'谁', '誰'}:
        return 2.0
    if '什么' in w or '什麼' in w:
        return 0.95
    words = re.findall(r"[\w']+", before.lower())
    last = words[-1] if words else ''
    if w in {'specific', 'certain', 'particular'}:
        if w == 'certain':
            return 0.9
        if w == 'particular' and last == 'in':
            return 0.15
        return 2.0 if last in {'a', 'any', 'one'} else 1.0
    if w == 'every':
        return 1.1
    if w == 'which':
        if token.strip().istitle() and before.endswith('\n'):
            return 2.0
        q = question_level(before)
        if q:
            return q
        if last in {'and', 'or', 'means', 'is'}:
            for match in re.finditer(r'\bwhich\b', before[-140:].lower()):
                if question_level(before[-140:][:match.start()]) >= 5:
                    return 6.0
        if token.strip().istitle():
            return 2.0
        return 2.5 if last in {'and', 'but', 'or'} else 0.25
    if w == 'what':
        return 1.15 if question_level(before) else 0.63
    if w in {'who', 'whom', 'whose'}:
        return 2.0 if question_level(before) else -0.05
    if w in QUALITY:
        return 1.4 if question_level(before) else 0.4
    if w == 'per':
        return 0.9 if token == ' per' else 0.0
    if w in {'one', 'single'}:
        return 0.64 if w == 'single' else 0.34
    if w == 'whichever':
        return 4.2
    if w in {'a', 'the'} and roots(last) & {'choose', 'select', 'pick', 'find'}:
        return 1.5 if w == 'a' else 0.3
    if w == 'of' and last in {'type', 'kind', 'sort', 'name', 'choice', 'selection'}:
        return 0.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, before) - (0.2 if not before else 0.0)
    return (doc, (before + token)[-180:]), float(value)

"""A sparse approximation of the component's negative numerical-relation signal.

Equality signs, arithmetic words and copulas respond to preceding numerals and
arithmetic notation. Longer, standalone numerical values strengthen operator
responses; year-like numbers and letter-attached identifiers are discounted.
Spaces after numerical relation phrases get a weaker signal. Positive responses
and most small lexical variations are intentionally not modeled.
"""
import re

READS = ()
COPULAS = set('is be are was were being been becomes become'.split())
EQUALITY = set('equal equals equivalent identical'.split())
ARITHMETIC = set('''plus minus times divided multiplied added subtract
    subtracting adding divide multiply remainder sum difference product ratio
    fraction half quarter percent percentage squared cubed'''.split())
COMPARISONS = set('''less more greater smaller bigger larger close closest closer
    near nearest nearly between past over under than beyond above below'''.split())
CUES = set('''divided multiplied added equal equals plus minus times percent
    percentage ratio difference sum product close closest closer squared cubed'''.split())
FUNCTION_WORDS = set('''is are be was were been being with without and or plus
    minus times divided multiplied equals equal than over under between at to
    from of for by in as not'''.split())
FRACTIONS = set('half quarter percent percentage fraction'.split())
MATH_SIGNS = set('=+*×÷≈^')
RELATION_WORDS = ARITHMETIC | EQUALITY | COMPARISONS | {'itself'}


def role(token):
    word = token.strip().lower()
    if not word:
        return 'space' if not any(c in token for c in '\n\r\t') else None
    if word in ('squared', 'cubed'):
        return 'power'
    if word in COPULAS:
        return 'copula'
    if word in EQUALITY:
        return 'equality'
    if word in ARITHMETIC - FRACTIONS - {'squared', 'cubed'}:
        return 'arithmetic'
    if word == 'by':
        return 'by'
    if any(c in word for c in '≈≃≅'):
        return 'approximation'
    if word.count('=') == 1:
        return 'equals'
    if any(c in word for c in '×*'):
        return 'times'
    if '+' in word:
        return 'plus'
    if word in ('-', '−', '–', '—'):
        return 'minus'
    return None


def response(token, text, previous):
    kind = role(token)
    if kind is None:
        return 0.0
    tail = text.rstrip()
    word = re.search(r'[a-zA-Z]+$', tail)
    prev_word = word[0].lower() if word else ''
    if kind == 'by':
        return -1.363 * (prev_word in CUES)
    if kind == 'equality':
        return -.840 * any(any(c.isdecimal() for c in s) for s in previous)
    notation = min(1, sum(c in MATH_SIGNS for c in tail[-48:]) / 4)
    if kind == 'space':
        near = any(any(c.isdecimal() for c in s) for s in previous[-3:])
        relation = (prev_word in {'to', 'by', 'of', 'with', 'and', 'as', 'for'}
                    and any(s.strip().lower() in RELATION_WORDS
                            for s in previous[-3:-1]))
        return -.208 * near * notation - .698 * relation
    density = sum(c.isdecimal() for c in tail[-48:]) / 48
    if kind == 'power':
        return -12.081 * density
    numbers = list(re.finditer(r'[\d⁰¹²³⁴⁵⁶⁷⁸⁹]+', tail))
    last = numbers[-1] if numbers else None
    gap = tail[last.end():] if last else ''
    end = bool(last and not gap and len(last[0]) <= 12)
    length = min(4, len(last[0])) / 4 if end else 0.0
    if kind == 'copula':
        return -1.701 * density - 1.755 * end * notation
    if kind == 'arithmetic':
        return -3.310 * length
    # Distinguish values from identifiers, year-like dates and numbered labels.
    before = tail[:last.start()].rstrip() if last else ''
    word = re.search(r'[a-zA-Z]+$', before)
    before_word = word[0].lower() if word else ''
    attached = bool(last and last.start() and tail[last.start()-1].isalpha())
    year = bool(last and last[0].isascii() and last[0].isdigit()
                and 1500 <= int(last[0]) <= 2099)
    value = bool(last and not attached and not year
                 and (not before_word or before_word in FUNCTION_WORDS))
    if kind == 'equals':
        phrase = value and len(gap) < 20 and gap.strip(' ,;()$') in (
            '', 'which', 'that', 'itself')
        return -1.072 * length - 1.718 * density - .954 * phrase
    if kind == 'approximation':
        return -2.428 * (end and value)
    scale = {'times': .830, 'plus': .906, 'minus': .432}[kind]
    return -scale * length * value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        text, previous = '', []
    else:
        _, text, previous = carry
    token = prefix.token_strings[-1]
    prediction = response(token, text, previous)
    carry = (document, (text + token)[-128:], (previous + [token])[-8:])
    return carry, float(prediction)

"""A local, grammatical approximation to an indefinite-article response.

Space-prefixed English a/an get a negative value determined by the previous
word: weak after copulas or reference verbs, stronger after prepositions
and concrete action verbs. An scales the response down. Capitalization,
hyphenated phrases, a few nominal-of phrases, and document starts have
separate rules. Romance indefinite articles get small constant responses;
other tokens get zero. This is not a full syntactic or language parser.

The word classes and strengths summarize training examples. They omit
finer word-specific and longer-context variation in the true component.
"""
