from functools import lru_cache
import wordnet

READS = ()

# Prepositions are closed-class grammatical words, not token IDs.
PREPOSITIONS = {
    'of': -1.5, 'in': -2.0, 'with': -1.8, 'as': -2.7,
    'to': -1.3, 'for': -1.2, 'on': -1.7, 'by': -1.4,
    'from': -0.9, 'at': -2.5, 'into': -2.5, 'like': -2.5,
    'about': -1.7, 'over': -0.8, 'through': -0.9,
    'within': -2.7, 'during': -3.0, 'without': -4.1,
    'after': -0.6, 'before': -1.0, 'under': -1.6,
    'between': -1.2, 'against': -1.5,
}
COPULAS = {
    'is': -0.5, 'are': -0.3, 'was': -1.0, 'were': -0.9,
    'be': -1.3, 'been': -1.6, 'being': -1.5, 'am': -1.0,
}


@lru_cache(maxsize=8192)
def word_strength(word):
    if word in PREPOSITIONS:
        return PREPOSITIONS[word]
    if word in COPULAS:
        return COPULAS[word]
    if word in {'and', 'or', 'but'}:
        return -0.8
    if word in {'if', 'when', 'where', 'which', 'that'}:
        return 0.1
    if word in {'than', 'either', 'both'}:
        return -1.7
    if word in {'half', 'quarter'}:
        return -3.6
    if word in {'the', 'a', 'an'}:
        return 0.2
    if word in {'not', 'such', 'also', 'just'}:
        return -1.9
    if word in {'only', 'even'}:
        return -0.5
    if word in {'up', 'out'}:
        return -2.3
    if word in {'it', 'you', 'me', 'him', 'her', 'us', 'them'}:
        return -2.1
    bases = set(wordnet.base_forms(word, 'verb'))
    # Reference/description verbs introduce a relatively weak response.
    if bases & {'show', 'represent', 'illustrate', 'indicate', 'mean',
                'suggest', 'consider', 'remain', 'follow', 'describe'}:
        return -0.4
    # Concrete possession and administrative/transfer actions.
    if bases & {'wear', 'own', 'issue', 'file', 'sign', 'send', 'post',
                'submit', 'leave', 'miss', 'book', 'schedule', 'hire'}:
        return -4.6
    # Creation, initiation and performance of an activity.
    if bases & {'make', 'create', 'build', 'craft', 'do', 'produce',
                'generate', 'start', 'initiate', 'launch', 'perform'}:
        return -3.4
    if bases & {'have', 'get', 'take', 'become'}:
        return -2.2
    if bases & {'provide', 'use', 'give', 'offer', 'include', 'need', 'see'}:
        return -1.4
    if 'verb' in wordnet.parts_of_speech(word):
        return -1.8 - 0.3 * word.endswith('ed') + 0.3 * word.endswith('s')
    return -0.7


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    text = prefix.token_strings[-1]
    value = 0.0
    if text in {' a', ' an', '-a', '-an', '-A', ' AN', ' A', ' An'}:
        m = re.search(r'([A-Za-z]+)$', tail)
        if previous.strip() in {"'s", '’s'}:
            value = -1.3
        elif m:
            word = m.group(1)
            value = word_strength(word.lower())
            if word[0].isupper() and not word.isupper():
                if word.lower() in PREPOSITIONS:
                    value = 0.3 if word.lower() == 'for' else value * 0.55
            if word.lower() == 'of' and re.search(
                r'\b(?:absence|presence|lack|creation|bit) of$', tail.lower()
            ):
                value = -4.9
        elif tail.endswith('.'):
            value = 0.7
        elif tail.endswith(',') or tail.endswith(';'):
            value = -0.2
        elif tail and tail[-1] in '=+*/<>':
            value = 0.4
        elif not tail:
            value = 0.4
        else:
            value = 0.0
        if text in {' A', ' An'} and not (
            m and (m.group(1).isupper() or value < -3.0)
        ):
            value = -0.1
        if text in {' an', '-an', ' AN', ' An'}:
            value *= 0.68
        if text.startswith('-'):
            value *= 1.8
            if re.search(r'-(?:of|at|as)$', tail.lower()):
                value = -6.5
    elif text in {'a', 'A', 'an', 'An'} and not tail:
        value = {'a': 1.0, 'A': 0.8, 'an': 0.45, 'An': 0.3}[text]
    elif text in {' un', "'un", '’un', ' um'}:
        value = -0.7
    elif text in {' una', ' une', "'une", ' uma'}:
        value = -1.15
    return (doc, text, (tail + text)[-100:]), value

"""Detect source-listing gutters rather than the code's meaning.

Space-padded line numbers produce a positive pulse that fades across digits.
Earlier numbered lines establish confidence. Also recognize unpadded grep and
web listings, patch signs, and repeated comment/table prefixes. Other tokens
get zero.
"""
import re
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, previous, seen, style, patch, comments = '', '', 0, '', 0, 0
    else:
        _, line, previous, seen, style, patch, comments = carry
    token = prefix.token_strings[-1]
    value = 0.0
    match = re.fullmatch(r'( *)([0-9]*)', line)
    if len(token) == 1 and token in '0123456789' and match:
        spaces, digits = map(len, match.groups())
        confidence = (0.3, 0.75, 0.9, 1.0)[min(seen, 3)]
        if 2 <= spaces <= 5:
            height = (1.55, 2.0, 1.95, 1.6)[spaces - 2]
            decay = 0.83 if spaces == 2 else 0.72
            end = previous.rstrip()[-1:]
            height += 0.35 if end == ';' else 0.2 if end == '{' else 0
            height -= 0.35 if end in ('(', ',') else 0
            value = height * decay ** digits * confidence
        elif spaces <= 1 and style:
            if style == 'nbsp':
                value = 2.5 * 0.85 ** digits * confidence
            elif style == 'context':
                value = 2.0 * 0.8 ** digits * confidence
            elif style == 'colon':
                value = (0.9 + 0.1 * min(digits, 3)) * confidence
            else:
                value = 1.6 * 0.8 ** digits * confidence
    if re.fullmatch(r' *[0-9]+', line):
        delimiters = (':', '-', '\xa0', '\n')
        if token in delimiters and style in ('colon', 'context', 'nbsp'):
            value = (1.2 if token == ':' else 0.65) * min(seen, 2) / 2
    stripped = token.strip()
    if not line.strip():
        if stripped in ('+', '-') and patch:
            value = (2.25 if stripped == '-' else 1.6) * min(patch, 2) / 2
            if '\n' in token:
                value *= 0.45
        elif stripped in ('//', '#', '/*', '*', '|') and comments:
            value = min(comments, 3) / 3 * 0.55
    line += token
    if '\n' in token:
        previous, line = line.rsplit('\n', 1)
        last = previous.rsplit('\n', 1)[-1]
        # grep uses ':' for matches and '-' for surrounding context.
        number = re.match(
            r' *[0-9]+(\t|:(?![0-9])|\xa0|-(?=\s|$))', last
        )
        if number:
            seen = min(seen + 1, 4)
            separator = number[1]
            if separator == '-' or (
                separator == ':' and style == 'context'
            ):
                style = 'context'
            else:
                style = {'\t': 'tab', ':': 'colon', '\xa0': 'nbsp'}[separator]
        elif not re.fullmatch(r' *[0-9]+', last):
            seen = max(seen - 1, 0)
            if not seen:
                style = ''
        if last.startswith(('@@', 'diff --git', '```diff')):
            patch = 2
        elif re.match(r'^[+-](?:\t|[^\s+\-])', last):
            patch = min(patch + 1, 3)
        elif last.startswith(('</tool_response>', '<|im_', '```')):
            patch = 0
        if re.match(r'\s*(//|/\*|\*|#|\|)', last):
            comments += 1
        else:
            comments = 0
    if len(line) > 200:
        line = '\0' + line[-199:]
    return (doc, line, previous[-200:], seen, style, patch, comments), value

