            value = -2.0
            if text[0] in ACTIVITY_MOTION:
                value = -0.1
            elif text[0] in CAUSATIVE_MOTION:
                value = -4.1
        elif len(text) == 2 and text[-1] in '东東':
            value = -1.6
    if text == '동':
        value = -5.3 if raw.startswith(b' ') else -3.8
        if before[-1:] and before[-1:] in '활운이':
            value = -1.0
    elif text.lower() == 'dong':
        value = -8.0
    elif text == 'động':
        value = -5.2
        if context.rstrip().endswith(('hanh', 'hoat')):
            value = -1.0
    elif text == 'đồng':
        value = -2.6
    elif text.lower() == 'ong':
        value = -10.0 if context.endswith('d') else 0.5
    elif text.lower() == 'ng':
        value = -8.3 if context.rstrip().endswith('d') else 0.2

    if text == 'ู' and before.endswith('ด'):
        value = 3.7
