"""Recognize context-anchored fragments of source-code syntax.

The main positive cases are control-flow parentheses, joining/interpolating
strings, printf conversions, JSON openings, URLs and Java namespace prefixes.
Printing calls and loop declarations receive smaller responses.  Ordinary text
is near zero.  An initial Title: header, a bare // newline, a CR-only prefix and repeated
middle dots have separate formatting rules. State resets per document.
"""
import re

READS = ()
CONTROL = {'if', 'while', 'catch', 'switch', 'for', 'foreach'}
PRINTING = {'print', 'printf', 'println', 'fprintf', 'kprintf', 'die',
            'log', 'info', 'debug', 'error', 'warn', 'warning', 'trace'}
JAVA = {'org', 'com', 'net', 'cn'}
JAVA_STANDARD = {'util', 'io', 'lang', 'net', 'nio', 'math', 'time', 'awt', 'sql'}
QUOTES = ('"', "'", '`')


def in_fstring(text):
    """An f-prefixed quote with no closing quote in the retained suffix."""
    for match in re.finditer(r'\bf\\*([\'\"])', text):
        if match[1] not in text[match.end():]:
            return True
    return False


def predict(t, p, history, only_cr):
    s, w = t.strip(), p.strip()
    if t == '\r':
        return 3.3 if only_cr else -0.04
    if not history and t == 'Title':
        return 0.66
    if not history and t == '//\n':
        return 6.8
    if history == 'Title' and t == ':':
        return -5.85

    # A keyword anchors the following condition or loop initializer.
    if s.startswith('(') and w in CONTROL:
        if w in {'for', 'foreach', 'switch', 'catch'}:
            return 2.2
        return 1.3 if s.startswith(('(!', '(*')) else 1.6
    if s.startswith('(') and w == 'import':
        return 1.35
    if s in {'int', 'var', 'let', 'const'} and re.search(
            r'\bfor\s*\($', history):
        return 1.2

    # Operators immediately following a quoted string.
    if p.rstrip().endswith(QUOTES):
        if t.startswith((' +', ' .', ' %')):
            return {'+': 2.1, '.': 2.15, '%': 2.4}.get(s, 2.0)
        if s == '<<':
            return 2.0
    if s == '<<' and w.endswith(('cout', 'cerr', 'clog')):
        return 1.2
    if (len(s) == 1 and s in 'diuoxXfFeEgGaAcspvqb' and
            re.search(r'%[-+0-9.#]*$', history[-30:])):
        return 1.4
    if t == ' %' and not (w.isdigit() or w in {')', 'of', '×'}):
        return 1.0
    if '${' in t:
        return 1.5 if t.startswith(' ') else 0.6
    if '{' in t and in_fstring(history + t.split('{')[0]):
        return 2.0 if t.startswith(' ') else 1.4
    if t == 'format' and p.endswith('.'):
        return 2.0

    if t == ' {\n' and (w == 'struct' or
                            re.search(r'\d+\t[ \t]*$', history)):
        return 0.73
    if t == '{"':
        return 0.8
    if s.startswith('[{'):
        return 0.6
    if s.startswith('{') and ('"' in s or "'" in s):
        return 0.25
    if t == '://':
        return 1.65 if w.lower().endswith(('http', 'https')) else 0.0
    if t == 'www':
        return 0.9
    if s in JAVA and w in {'import', 'package', 'static', 'new'}:
        return 1.8 if s == 'org' else 1.3
    if t in {'/org', '/com'}:
        return 1.0
    if t.startswith('.') and t[1:] in JAVA_STANDARD and w == 'java':
        return 0.95

    function = w.rsplit('.', 1)[-1]
    if s.lstrip('!').startswith(('("', "('", '(f', '(`')):
        if (function.lower() in PRINTING or
                function.lower().rstrip('f') in PRINTING or
                function.endswith(('Error', 'Exception'))):
            return 0.8
    if (t.startswith('.') and t[1:].lower() in PRINTING and
            w in {'log', 'logger', 'logging', 'console'}):
        return 1.3
    if len(s) >= 2 and set(s) == {'·'}:
        return 0.72
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        p, history, only_cr = '', '', True
    else:
        _, p, history, only_cr = carry
    t = prefix.token_strings[-1]
    value = predict(t, p, history, only_cr)
    return (doc, t, (history + t)[-180:], only_cr and t == '\r'), value

