"""Layer-1 MLP down_proj component 19: a rule-based reading of its firing contexts.

The component is quiet almost everywhere (typical size 0.1) and fires on a few kinds of
code and text boundary tokens. Each rule is a concept a reader can check; the value is
the mean activation in that case on training text:

1. URL scheme: "://" right after "http" or "https"                     ~1.6
2. Package path: "org", "com", ".util" ... after "import" or "java"    ~1.4
3. Control-flow paren: "(" right after if / for / while / catch         ~1.5
4. String joining: "+" or "<<" right after a closing quote              ~1.7
5. printf-style format: "%" after a quote, colon or "="                 ~1.5
6. Conversion letter (d, s, v, q, ...) right after "%"                  ~1.4
7. Opening quote-paren right after print / log / throw / raise / Error   ~0.8
8. Brace opening a dict or block after ":", "):" or at a line start     ~0.9
9. Any other " {" token                                                  ~0.35
10. String interpolation opener "${" or "{_"                             ~1.1

Everything else predicts 0.
"""
READS = ()

CONTROL = {"if", "for", "while", "catch", "switch", "foreach"}
PACKAGE = {"org", "com", "net", "io", "br", "cn", "www", "util", "apache", "springframework"}
PACKAGE_PREV = {"import", "java", "package", "http", "https", "://", "/", "org", "com", "repository"}
FORMAT_LETTER = {"d", "s", "v", "q", "f", "x", "u", "lu", "02x"}
MESSAGE_CALL = {"print", "printf", "println", "log", "throw", "raise", "Error", "perror", "alert",
                "info", "warn", "Printf", "Sprintf", "WriteLine", "Fatalf"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    tok = raw.strip()
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        raw_before = prefix.token_strings[-2]
    else:
        raw_before = ""
    before = raw_before.strip()
    prev = before.lstrip("./")

    if raw == "://" and before in ("http", "https"):
        return None, 1.6
    if tok.lstrip("./") in PACKAGE and prev in PACKAGE_PREV:
        return None, 1.4
    if tok.startswith("(") and prev in CONTROL:
        return None, 1.5
    if tok in ("+", "<<") and before[-1:] in ('"', "'"):
        return None, 1.7
    if tok == "%" and before[-1:] in (":", "'", "=", '"'):
        return None, 1.5
    if before.endswith("%") and tok in FORMAT_LETTER:
        return None, 1.4
    if (tok.startswith('("') or tok.startswith("('")) and prev in MESSAGE_CALL:
        return None, 0.8
    if raw in (" {", "{", '{"') and (before in (":", '"):', "}:") or raw_before.endswith("\n")):
        return None, 0.9
    if raw == " {":
        return None, 0.35
    if tok.startswith("${") or tok.startswith("{_"):
        return None, 1.1
    return None, 0.0

