response to 'or' and fixed whitespace/dot-marker rules. Other values are zero.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# Translations of 'and': language(s), ordinary activation.
CONJUNCTIONS = {
    'et': ('fr', 1.00),
    'und': ('de', 0.83),
    'e': ('it pt', 1.30),
    'ed': ('it', 1.35),
    'y': ('es', 1.15),
    'i': ('pl', 1.00),
    'oraz': ('pl', 0.60),
    've': ('tr', 0.95),
    'si': ('ro', 1.75),
    'și': ('ro', 1.05),
    'şi': ('ro', 1.30),
    'és': ('hu', 0.56),
    'og': ('nb da', 1.20),
    'och': ('sv', 1.20),
    'en': ('nl', 1.00),
    'ja': ('fi', 1.10),
    'dan': ('id', 1.15),
