    lang for langs, _ in CONJUNCTIONS.values() for lang in langs.split()
}))
WORDS = re.compile(r'[^\W\d_]+')

@lru_cache(maxsize=65536)
def frequency(word, language):
    return zipf_frequency(word, language)


def language_gate(context, languages, competitors=LANGUAGES):
    words = [w for w in WORDS.findall(context.lower()) if len(w) > 1][-8:]
    if not words:
        return 0.0
    wanted = languages.split()
    def score(lang):
        return sum(frequency(w, lang) for w in words) / len(words)
    advantage = max(map(score, wanted)) - max(
        score(lang) for lang in competitors if lang not in wanted
    )
