        elif lower == 'і':
            value = 1.05
        elif lower == 'و':
            persian = language_gate(context, 'fa', ('ar', 'fa'))
            value = 0.15 + persian * (1.0 + 0.5 * punctuated)
        elif lower == 'or':
            value = -0.09

    # Greek 'and' often ends in a separate token; join its bytes first.
    joined = (old + raw).decode('utf-8', errors='ignore').lower()
    if re.search(r'(?<!\w)κ(?:αι|αί|αὶ)$', joined):
        value = 2.35

    formula = bool(re.search(
        r'\\(?:frac|right|left|hfill|begin|sum|mu|sqrt|nonumber|alpha|vec|hat'
        r'|big|overline|mathrm|beta|gamma|delta|theta|matrix)', context
    ))
    if '\\\\' in token:
        value = -1.30 if formula else 1.20
    elif token.startswith('\\"') and previous.endswith('\\\\'):
        value = 1.15
    elif token.endswith('*\\'):
        value = 1.05  # An asterisk followed by a string escape.
    elif token == 'cr' and context.endswith('\\'):
        value = -2.80  # TeX's alternative row-break command.

    if token == ':' and context == 'Title':
        value = 10.05
    elif token == '//\n' and not context:
        value = 15.11
    elif token == '\r' and not context.strip('\r'):
        value = 11.37
    elif token and not token.strip('\xa0'):
        value = 0.15
    elif len(token) >= 2 and set(token) == {'·'}:
        value = -0.58

    return (doc, (old + raw)[-512:]), float(value)

"""A sparse approximation for title and source-documentation punctuation.

Predict a large positive pulse at document-opening 'Title:', and smaller
positive pulses at title separators, parameter/return fields, references,
and XML documentation boundaries. Documentation @ signs, comment labels,
and closing bold headings are negative. Empty /** openers strengthen the
@ response. A few code/whitespace opening forms have separate responses.

Amplitudes summarize training examples. Ordinary text is left at zero;
lexical background variation and partial-byte Korean effects are omitted.
"""
import re

READS = ()
TYPE_WORDS = {'int', 'string', 'void', 'bool', 'float', 'double', 'char'}
DOC_FIELDS = (
    r':(?:param|type)\s+\w+$|:(?:return|rtype|toctree)$|'
    r'@(?:param|returns?|description|desc)(?:\s+\w+)?$'
)
COMMENT_LABEL = (
    r'(?:#|//|/\*|\*)[^\n]*'
    r'(?:TODO|FIXME|NOTE|pylint|noqa)\s*$'
)


def response(s, tail, opening, position):
    text = tail.replace('\\n', '\n')
    line = text.rsplit('\n', 1)[-1]

    if s in (':', '：'):
        if position == 1 and opening == 'Title' and s == ':':
            return 10.23
        if re.search(r'#\s*-\*-\s*coding$', line):
            return -3.5
        if re.search(COMMENT_LABEL, line):
            return -1.6
        if re.search(DOC_FIELDS, line):
            return 2.1
        if re.search(r'@\w+\s*$', line):
            return .35
        # Short capitalized labels in block comments.
        if re.search(r'(?:/\*|\*|>)\s*[A-Z][A-Za-z]*'
                     r'(?: [A-Za-z]+){0,2}\s*$', line):
            return -.5
        if line.count('**') % 2 and not re.search(r'\d$', line):
            return -.25
        if position < 40 and '\n' not in opening and ':' not in opening:
            words = re.findall(r'[A-Za-z]+', opening)
            capitals = sum(w[0].isupper() for w in words)
            title_case = capitals >= 2 and capitals >= .5 * len(words)
            if (title_case and len(words) >= 3
                    and not re.search(r'[\d{}=()\\]', opening)
                    and re.search(r'\b(of|and|in|on|for|the|with|their)\b', opening)):
                return .63

    if re.search(r'@return\s*$', line) and s.strip() == 'void':
        return 2.2
    if re.search(r'@see\s*$', line) and s in (' #', ' <'):
        return 1.9
    if (s.strip() in ('Created', 'Copyright')
            and re.search(r'/\*\*?\s*(?:\*\s*)?$', text)):
        return -1.9
    if s.strip() == '@':
        start = text.rfind('/*')
        star_line = re.search(
            r'(?:^|\n)\s*(?:\d+\s+)?(?:\*|///)\s*$', text)
        if start > text.rfind('*/') or star_line:
            part = text[start:] if start >= 0 else text
            if part.endswith('/**'):
                return -2.9
            if re.fullmatch(r'/\*\*\s*(?:\d+\s+)?\*?\s*', part):
                return -1.9
            return -.4

    if s == '**' and line.count('**') % 2:
        before, bold = line.rsplit('**', 1)
        heading = re.fullmatch(r'\s*(?:[-*]|\d+\.)?\s*', before)
        if heading and len(bold.strip()) > 1 and not re.search(r'[`?:：]', bold):
            return -.8 if before.strip() else -.3
        if '|' in before and len(bold) > 1:
            return -.7
    if s == '.' and re.fullmatch(r'\s*#{3,6}\s+\d+', line):
        return .23

    if s == ' <' and re.search(r'///\s*$', line):
        return .6
    if '///' in line:
        if s == '></':
            return 2.0
        if s in ('"></', '">') and re.search(r'<param\s+name=', line):
            return .8
    if s == '>':
        if '#include' in line:
            return -.6
        if re.search(r'<(summary|title|p|b|em|issue_description|pr_description)$', line):
            return -.32

    if position == 0:
        if s == '//\n':
            return -5.74
        if s.strip() in TYPE_WORDS:
            return -3.15 if s == s.strip() else -.52
        if s == '\r':
            return -2.34
        if s == '\\t':
            return -1.39
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0)
    _, tail, opening, position = carry
    s = prefix.token_strings[-1]
    value = response(s, tail, opening, position)
    state = (doc, (tail + s)[-512:], (opening + s)[:400], position + 1)
    return state, value

"""Local determiner phrases, chiefly the negative signal on 'of the'.

Genitives are stronger than partitives ('one/some of the') and connectives
('because of the'). Smaller rules cover other preposition/article pairs,
Romance article forms and forum labels. At document openings, escaped
whitespace, NUL and opening quotes receive large positive values; so does
the colon in an initial 'Title:' field. Repeated identical opening tokens
keep their opening value. Everything else defaults to zero.
"""
READS = ()

PARTITIVE = set('one any most many few several both'.split())
CONNECTIVE = set('because instead think thinking'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, position, leading = '', '', 0, True
    else:
        _, previous, before, position, leading = carry
    text = prefix.token_strings[-1]
    leading = leading and (position == 0 or text == previous)
    word = text.strip().lower()
    prev = previous.strip().lower()
    value = 0.0

    if word == 'the':
        value = -0.15 if text == 'the' else 0.0
        if prev == 'of':
            value = -0.76
            if before in PARTITIVE or before == 'part':
                value = -0.40
            elif before in ('each', 'all', 'none', 'out', 'lot'):
                value = -0.52
            elif before == 'some' or before in CONNECTIVE:
                value = -0.24
            if position == 1:
                value = -1.06
            if text.strip() == 'The':
                value *= 0.6
            elif text.strip() == 'THE':
                value *= 0.8
        elif prev in ('for', 'by', 'among'):
            value = -0.25
        elif prev in ('to', 'with', 'between'):
            value = -0.19
        elif prev in ('from', 'after', 'before', 'if', 'when', 'where',
                      'which', 'around', 'against', 'all'):
            value = -0.12
        elif prev in ('in', 'on', 'under'):
            value = 0.07 if previous.strip().islower() else 0.24
        elif prev in ('and', 'or', 'as', 'through'):
            value = -0.07
        elif previous.endswith('.'):
            value = 0.15
        elif previous == ',':
            value = 0.05 if text.strip() == 'the' else -0.16
    elif word in ('a', 'an'):
        if prev == 'of':
            value = -0.46
        elif prev in ('for', 'by', 'to', 'using', 'about'):
            value = -0.22
        elif prev in ('in', 'into', 'from', 'as', 'on', 'at', 'such', 'through'):
            value = -0.15
        elif prev in ('is', 'was', 'are', 'be', 'has', 'had', 'have'):
            value = 0.09
        elif prev in ("'s", '’s'):
            value = 0.18
        elif previous == ',':
            value = -0.05
    elif prev == 'of' and word in (
        'this', 'that', 'these', 'those', 'our', 'your', 'their',
        'his', 'her', 'its', 'each', 'them', 'which',
    ):
        value = -0.18
    elif text.startswith(' ') and text.strip().islower():
        if word in ('del', 'della', 'dello', 'delle', 'dei', 'degli', 'dell'):
            value = -0.48 if word == 'della' else -0.34
        elif word in ('du', 'da', 'dos', 'das'):
            value = -0.20
        elif word in ('le', 'les', 'el', 'die', 'den', 'der'):
            value = 0.15
    if word == 'tags' and prev == 'show':
        value = 1.2
    elif word == 'views' and (prev.isdigit() or prev == 'k'):
        value = 0.65
    elif text == 'udos' and previous.strip() == 'K':
        value = 0.55
    # These distinguish literal backslash escapes from actual whitespace.
    if leading:
        if text == r'\t':
            value = 8.2
        elif text == r'\n':
            value = 5.8
        elif text == '\0':
            value = 6.3
        elif text == r'\"':
            value = 3.7
        elif text == '"':
            value = 2.45
        elif text == '“':
            value = 1.65
        elif text == '\t':
            value = 1.29
    elif position == 1 and previous == 'Title' and text == ':':
        value = 5.24
    return (doc, text, prev, position + 1, leading), value

"""A twelve / digit-pair response, plus a document-onset offset.

A final 2 is excited most by a preceding 1, less by other odd digits;
decimal and comma separators weaken this response. Twelve in words and
December also excite it. K-12 and a Chinese year marker strengthen 12.
At document onset, word tokens instead tend to have a negative response,
stronger for long words and weaker for single letters. An initial 12
reverses its usual sign; bare carriage-return onsets are strongly negative.
Repetitions of the initial token keep its onset value. Chinese 十二 and
Roman XII are included. These are coarse averages, not token lookups.
"""
READS = ()


def onset(token):
    word = token.strip()
    if token == '\r':
        return -6.9
    if token.startswith('<|'):
        return -0.40
    if token.isspace():
        return -0.03
    if token.isdigit():
        return -0.23
    if word.isalpha():
        if word.isascii():
            value = -0.52 if token.startswith(' ') else -0.68
            if len(word) == 1:
                value += 0.18
            elif len(word) >= 8:
                value -= 0.14
            return value
        return -0.35
    if any(c.isalpha() for c in token):
        return -0.52
    return -0.27


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    recent, position, initial = ('', 0, token) if start else carry[1:]
    if token != initial:
        initial = None
    value = -0.003
    if token == '2':
        value = -0.025
        digits = recent
        separated = bool(digits) and digits[-1] in '.,'
        if separated:
            digits = digits[:-1]
        digit = digits[-1:]  # Last digit of the current number.
        if digit and digit in '0123456789':
            if digit == '1':
                value = 0.90
                if digits.endswith(('K-1', 'K1')):
                    value = 1.75
                elif digits.endswith('年1'):
                    value = 1.50
                elif len(digits) > 1 and digits[-2].isdigit():
                    value = 0.65
            elif int(digit) % 2:
                value = 0.45
            elif digit == '4':
                value = 0.14
            else:
                value = -0.04 if digit in '02' else 0.0
            if separated:
                value = 0.4 * value + 0.02
        if position == 1 and recent == '1':
            value = -2.19
    word = token.strip().lower()
    if word == 'twelve':
        value = 0.93
    elif word == 'december':
        value = 0.54
    elif word == 'dec':
        value = 0.10
    elif '十二' in token:
        value = 0.65 if token == '十二' else 0.45
    elif token == '二' and recent.endswith('十'):
        value = 0.65
    elif word == 'xii':
        value = 0.23
    if initial is not None:
        value = onset(token)
    return (doc, (recent + token)[-16:], position + 1, initial), value

"""A small lexical/boundary approximation, not a general posture classifier.

Positive spikes mark Chinese prone/leaning postures and knocking; the
character 呂 (also 吕) is another strong lexical trigger. Sentence-ending
exclamations/ellipses are positive after function words; a period after
"the" is also positive, as in an unfinished phrase.
Document starts are usually negative, especially a leading spaced period
and the second digit of initial '12'.
Homogeneous opening runs of decorative marks or letters are more negative.
Most other tokens receive a near-zero prediction. Small lexical fluctuations
and less common context-sensitive spikes are deliberately left out.
"""
READS = ()

# Basic posture verbs: lie low, lie/crouch, and lie face down.
POSTURES = {
    '伏': 3.8,
    '卧': 5.4,
    '趴': 2.1,
    '趴在': 2.1,
}
KNOCKING = {
    '扣': 6.8,  # knock, fasten, or dunk
    '叩': 2.6,  # knock or kowtow
}
FUNCTION_WORDS = frozenset('''
    a an the to for of in on by with at as
    and or can will we they that is are
'''.split())
SENTENCE_ENDS = frozenset(('.', '!', '..', '...', '....', '.!', ',!'))
DECORATIVE_MARKS = frozenset('!?·^~\\:')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    b = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        n, opening, previous, tail, uniform = 0, '', '', b'', True
    else:
        _, n, opening, previous, tail, uniform = carry
        uniform = uniform and s == previous
    if n < 3:
        opening = (opening + s)[:4]

    value = 0.002
    if n == 0:
        value = -0.10 if s.startswith(' ') else -0.23
        if s == ' .':
            value = -2.1
    if n == 1 and opening == '12':
        value = -3.24
    elif n == 2 and opening == '122':
        value = -1.25
    elif n and s in SENTENCE_ENDS:
        previous_word = previous.strip().lower()
        if previous_word in FUNCTION_WORDS:
            if '!' in s:
                value = 0.85
            elif s != '.':
                value = 0.33
            elif previous == ' the':
                value = 0.45

    raw = tail + b
    text = raw.decode('utf-8', errors='ignore')
    word = s.strip()
    # A split UTF-8 character fires only when its final bytes arrive.
    if '\ufffd' in s and text and raw.endswith(text[-1].encode('utf-8')):
        word = text[-1]
    if word in POSTURES:
        value = POSTURES[word]
    elif word in KNOCKING:
        value = KNOCKING[word]
    elif word in ('吕', '呂'):
        value = 4.4 if text.endswith('風呂') else 3.0

    if uniform and len(s) > 1 and len(set(s)) == 1:
        decorative = s[0] == '·' or (
            len(s) >= 4 and s[0] in DECORATIVE_MARKS
        )
        repeated_letters = s.isascii() and s.isalpha() and (
            len(s) >= 4 or s.isupper()
        )
        if decorative or repeated_letters:
            value = -2.05

    return (doc, n + 1, opening, s, raw[-16:], uniform), value

"""A lexical recognizer for collections, alternatives, and broad coverage.

Most collection cues are positive; 'some' and resemblance-'like' are weakly negative.
Two preceding tokens distinguish partitives ('any of'), collective ranges
('a wide range of'), and comparisons from ordinary function words. 'Like'
after a plural-looking word is treated as an example introducer, unlike
'looks like'. 'Across' similarly separates distribution from crossing motion.
Chinese counting markers and several translated collection words are included.
The response strengths are rounded training estimates; unrecognized cues are 0.
"""
READS = ()
COUNT_CLASSIFIERS = frozenset("个個种種项項条條辆輛")
CHINESE_NUMERALS = frozenset("一二三四五六七八九十百千两兩几幾多数數")

# Familiar quantifiers have different response strengths.
QUANTIFIERS = {
    'all': 0.79,
    'both': 0.99,
    'every': 0.64,
    'few': 0.19,
    'many': 0.69,
    'more': 0.18,
    'most': 0.45,
    'multiple': 0.53,
    'several': 1.24,
    'some': -0.15,
    'various': 1.16,
}


def response(raw, prev, prev2):
    w = raw.strip().lower()
    if raw[:1].isascii() and raw[:1].islower() and prev[-1:].isalpha():
        return 0.0  # An attached English word-fragment, not a new word.

    if w == 'of':
        if prev == 'variety':
            return 3.3
        if prev in {'range', 'array', 'spectrum'}:
            return 2.8 if prev2 in {'a', 'wide', 'broad', 'full', 'vast'} else 0.5
        if prev in {'any', 'each', 'which', 'either', 'neither'}:
            return 2.2
        if prev in {'one', 'two', 'three', 'four', 'five', 'some', 'many',
                 'several', 'none', 'few', 'hundreds', 'thousands', 'millions'}:
            return 1.35
        if prev in {'all', 'both', 'most', 'couple', 'much', 'kinds', 'types',
                 'sorts', 'species', 'series', 'parts', 'stages', 'branches'}:
            return 0.75
        if prev in {'lot', 'lots', 'plenty'} or (
            prev == 'number' and prev2 in {'a', 'large', 'great', 'huge', 'significant'}
        ):
            return 0.55
    if w == 'as':
        if prev in {'such', 'well'}:
            return 1.0
        if prev2 == 'as':
            return 0.37
    if w == 'well' and prev == 'as':
        return 0.71
    if w == 'to' and prev in {'up', 'similar'}:
        return 0.39
    if w == 'than' and prev in {'more', 'less', 'greater', 'fewer'}:
        return 0.29
    if w == 'from' and prev in {'ranging', 'range', 'ranges', 'vary', 'varies',
                              'varying', 'different', 'everything', 'anything'}:
        return 1.25
    if w == 'all' and prev in {'in', 'to', 'on', 'from', 'across', 'through',
                            'nearly', 'almost'}:
        return 1.48
    if w in {'over', 'around'} and prev == 'all':
        return 2.3
    if w == 'ages' and prev == 'all':
        return 4.0
    if w in {'countries', 'cities', 'states', 'regions', 'nations'} and prev.isdigit():
        return 2.0
    if w == 'across':
        if prev in {'come', 'came', 'coming', 'walk', 'walking', 'walked',
                 'go', 'going', 'went', 'look', 'looking', 'reflecting',
                 'bridge', 'track'}:
            return 0.0
        if (prev.endswith('s') and prev not in {'is', 'was', 'this', 'has', 'as'}) or (
            prev in {'all', 'from', 'spread', 'distributed', 'scattered'}
        ):
            return 3.0
        return 1.25
    if w == 'like':
        if prev in {'look', 'looks', 'looked', 'looking', 'feel', 'feels', 'felt',
                 'seem', 'seems', 'seemed', 'sound', 'sounds', 'is', 'was'}:
            return -0.21
        if prev.endswith('s') and prev not in {'this', 'has', 'as', 'does'}:
            return 0.8
        if prev in {'something', 'someone', 'somebody', 'anything', 'anyone'}:
            return 0.4
        return 0.0

    if w in QUANTIFIERS:
        return QUANTIFIERS[w]
    if w == 'including':
        return 1.0
    if w in {'include', 'includes', 'included', 'named', 'called', 'namely'}:
        return 0.22
    if w in {'whole', 'entire', 'everything', 'everyone', 'everybody'}:
        return 0.45
    if w in {'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten'}:
        return 0.25
    if w in {'different', 'diverse', 'varying'}:
        return 0.49
    if w in {'variety', 'ranging', 'numerous', 'countless', 'myriad'}:
        return 1.3
    if w in {'wide', 'vary', 'varies', 'varied', 'widely'}:
        return 0.66
    if w in {'range', 'array', 'spectrum', 'over', 'since'}:
        return 0.2
    if w == 'around':
        return 0.4
    if w in {'among', 'amongst', 'especially', 'particularly', 'specifically'}:
        return 0.32
    if w == 'throughout':
        return 1.54
    if w in {'worldwide', 'nationwide', 'everywhere', 'globally'}:
        return 1.4

