    if w in COUNT_CLASSIFIERS:
        if prev.isdigit():
            return 2.05 if prev2.isdigit() else 1.24
        if prev in CHINESE_NUMERALS:
            return 1.24
    if w in {'各', '各个', '各种', '各種', '各项', '各項', '多项', '多項',
             '各类', '多种', '多样', '国内外'}:
        return 1.6
    if w in {'所有', '全部', '一切', '全', '整个', '全て', 'すべて',
             'todos', 'todas', 'todo', 'toda', 'tutti', 'tutte', 'tutto',
             'tous', 'toutes', 'tout', 'toute', 'alle', 'все', 'всех', 'всем'}:
        return 0.8
    if w in {'许多', '多个', '多く', '多数', 'varios', 'varias', 'plusieurs',
             'alcuni', 'различные', 'различных', 'различ'}:
        return 1.0
    if w in {'等', '等等', '包括', '包含', '比如', '诸如', '등'}:
        return 0.85
    if w == 'など':
        return 1.8
    if w in {'及', '以及', '并', '並', '，并'}:
        return 0.56
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, prev2 = ('', '') if carry is None or carry[0] != doc else carry[1:]
    raw = prefix.token_strings[-1]
    return (doc, raw.strip().lower(), prev), response(raw, prev, prev2)

