"""Layer 1 MLP down-projection, component 36: a sentence-boundary detector with a prose tilt.

In plain terms, this component:
* is strongly negative on the first token of each document (the token after
  <|endoftext|>, or the first token of a row), and on the filler token '··';
* is positive where a sentence or clause ends in running prose: a full stop, a
  line-ending full stop, 。, ! or ?; the strongest is a full stop ending a sentence,
  but a decimal point (a full stop right after a digit, as in 3.0) is almost off;
* is moderately positive on commas, colons, semicolons, brackets and dashes (less so
  after a digit, as in 1,000) and on clause-joining words such as "and", "who", "had",
  "as", "when", "with", "which";
* is weakly positive on articles and "to", and near zero on other words, copulas
  and CJK characters;
* is tilted by the surrounding text: it grows in narrative news or biography prose
  (pronouns such as he, she, his, her, who; past-tense reporting such as was, had,
  said; years, family, team, season) and shrinks in technical text (code, functions,
  variables, "use", "returns", "data", "value", "therefore", "Fig").

The prediction is one value per token type. The clause-level token types get a
tilt from a decaying count of context words (decay 0.98 per token, reset at each
document start). Values and tilt weights were set by a regression on 2048 training
rows and are rounded; the program reads only the prefix.
"""

READS = ()

DOC_START = -0.7
FILLER = "··"
FULL_STOP_LINE = {".\n", ".\n\n", "。\n", "。", "!\n", "?\n"}
FULL_STOP = {".", ".”", '."'}
OTHER_STOP = {"!", "?", "！", "？"}
COMMAS = {",", "，", ";", ":", "：", "、", ",\n", ";\n"}
OPENERS = {" (", "(", " –", " —", " -", ")", "),", ").", ")\n"}
JOINERS = {" and", " who", " had", " as", " when", " where", " with", " because", " but",
           " which", " that", " while"}
ARTICLES = {" the", " a", " an", " to"}
COPULAS = {" is", " was", " were", " are", " be", " been", " has", " have"}
PRONOUNS = {" he", " she", " his", " her", " they", " their", " them", " my", " who", " people",
            " him", " we"}
NARRATIVE = {" had", " was", " said", " told", " asked", " went", " years", " year", " ago", " family",
             " team", " week", " season", " night"}
TECHNICAL = {" function", " code", " data", " value", " values", " use", " using", " used", " number",
             " variable", " variables", " file", " line", " point", " each", " same", " different",
             " need", " such", " between", " if", " or", " not", " which", " because", " how", " may",
             " are"}
PUNCT_CLASSES = FULL_STOP_LINE | FULL_STOP | OTHER_STOP | COMMAS | OPENERS | JOINERS
DECAY = 0.98
PUNCT_TILT = 0.1
OTHER_TILT = 0.02


def ends_in_digit(text):
    return text.strip()[-1:].isdigit()


def is_cjk(text):
    return any(ord(ch) > 0x2E80 for ch in text)


def base_value(token, before):
    """The token's own activation level, before the context tilt."""
    if token == FILLER:
        return -1.66
    if token in FULL_STOP_LINE:
        return 0.35
    if token in FULL_STOP:
        return 0.05 if ends_in_digit(before) else 0.36
    if token in OTHER_STOP:
        return 0.18
    if token in COMMAS:
        return 0.07 if ends_in_digit(before) else 0.19
    if token in OPENERS:
        return 0.15
    if token in JOINERS:
        return 0.16
    if token in ARTICLES:
        return 0.10
    if token.strip() == "":
        return 0.05
    if token in COPULAS or is_cjk(token):
        return 0.02
    return 0.01


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc or carry is None:
        pronouns, narrative, technical = 0.0, 0.0, 0.0
    else:
        pronouns, narrative, technical = carry
    if new_doc:
        value = DOC_START
    else:
        before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
        value = base_value(token, before)
        tilt = pronouns + 2.0 * narrative - technical
        value += tilt * (PUNCT_TILT if token in PUNCT_CLASSES else OTHER_TILT)
    pronouns = DECAY * pronouns + (1.0 if token in PRONOUNS else 0.0)
    narrative = DECAY * narrative + (1.0 if token in NARRATIVE else 0.0)
    technical = DECAY * technical + (1.0 if token in TECHNICAL else 0.0)
    return (pronouns, narrative, technical), float(value)

programs.sol:
"""A start-of-document pulse, extended over repetitions of its first token.

Ordinary positions are nearly silent.  The initial pulse is smaller for bare
separators and digits, larger for words, especially capitalized words without
leading whitespace. NUL bytes have an especially strong opening pulse.
Character classes and a few grammatical classes estimate
its amplitude; they deliberately do not memorize individual word tokens.
"""
import unicodedata

READS = ()
PREPOSITIONS = set('in on at of to for from by with without into over under '
                   'between after before through about as'.split())
COPULAS = set('am is are was were be been being'.split())
CONJUNCTIONS = set('and or but nor so yet'.split())
ARTICLES = {'a', 'an'}


def start_strength(text):
    if "\x00" in text:
        return 27.2
    word = text.strip()
    if not word:
        if '\t' in text:
            return 11.3
        if '\n' in text:
            return 6.0 if text.count('\n') == 1 else 3.8
        return 3.0 if len(text) == 1 else 7.8
    if word.startswith('<|'):
        return 12.1
    if word.isdecimal():
        return 7.4
    if not any(c.isalnum() for c in word):
        if word[0] in '.,:;，。；、':
            return 2.0 if text.count('\n') >= 2 else 3.5
        if all(c in '-–—' for c in word):
            return 4.3
        if word == '(':
            return 5.6
        if word == ')':
            return 3.7
        if set(word) == {'#'}:
            return 10.0
        return 8.5
    letters = [c for c in word if c.isalpha()]
    if not letters:
        return 9.5
    script = unicodedata.name(letters[0], '').split(' ')[0]
    if script in {'CJK', 'HIRAGANA'}:
        return 9.5
    if script != 'LATIN':
        return 12.0
    leading_space = text[0].isspace()
    if word[0].isupper():
        return 11.1 if leading_space else 14.0
    if word in PREPOSITIONS:
        return 9.0 if leading_space else 9.7
    if word in ARTICLES:
        return 12.3 if leading_space else 14.4
    if leading_space and word in COPULAS:
        return 7.3
    if leading_space and word in CONJUNCTIONS:
        return 6.7
    return 11.0 if leading_space else 12.0



def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        return (document, prefix.token_ids[-1], True), start_strength(token)
    _, first, repeating = carry
    repeating = repeating and prefix.token_ids[-1] == first
    value = start_strength(token) if repeating else 0.0
    return (document, first, repeating), value

"""Approximate a mixed local spelling/phrase feature, not a general topic.

Positive rules cover Slavic tvor/var-like pieces, Latin place-name endings
(e.g. observ-atory, auditor-ium), laboratories and room compounds. Negative
rules cover East Asian ki syllables and fixed geographic/institutional names.
An initial 'Title:' label is another negative case. Unmatched tokens are near
zero. The byte history is short and resets at document boundaries.
"""
READS = ()


def activation(s, before):
    p = before.lower()
    w = s.strip().lower()
    if s == ':' and before == 'Title':
        return -3.59

    # Latin/Romance place-noun endings, at their tokenized completion.
    if s in ('atory', 'atories', 'atorio', 'atoria', 'atoire', 'atorium'):
        for stem, value in (('observ', 8.17), ('conserv', 5.45),
                            ('labor', 5.61), ('lav', 2.44), ('or', 2.44)):
            if p.endswith(stem):
                return value
    if s == 'ium' and p.endswith(('tor', 'lar', 'nar')):
        return 4.88
    if s == 'arius' and p.endswith('aqu'):
        return 4.47
    if s == 'ium' and p.endswith('r'):
        return 0.95
    if s in ('arium', 'atorium', 'orium', 'arius'):
        return 0.40

    # Rhotic syllables, especially Slavic tvor and word-internal var.
    if s == 'вор' and p.endswith('т'):
        return 4.76
    if s in ('вор', 'твор'):
        return 2.53
    if (s == 'wor' and p.endswith(('ot', 'st'))) or (s == 'or' and p.endswith('tw')):
        return 3.44
    if s == 'ř' and p.endswith(('vo', 'va')):
        return 3.88
    if s in ('var', 'vari', 'вар') and before and before[-1].isalpha():
        return 1.29
    if s.startswith(('ar', 'or', 'ар', 'ор')) and p.endswith(('v', 'w', 'в')):
        return 0.43
    if s in ('атор', 'тор'):
        return 0.59

    # Whole-word and compound facility names.
    if w in ('laboratory', 'laboratories', 'laboratoire'):
        return 2.59 if s.strip()[0].isupper() else 1.35
    if w == 'observatory':
        return 6.52
    if s == 'room' and p.endswith(('ball', 'sun', 'show', 'bed', 'bath', 'light')):
        return 2.84
    if w == 'room' and p.endswith('living'):
        return 2.78

    # Fixed geopolitical and institutional collocations.
    if w in ('korea', 'korean', 'koreans') and p.endswith(('north', 'south')):
        return -1.66
    if w == 'carolina' and p.endswith(('north', 'south')):
        return -0.70
    if w == 'kingdom' and p.endswith('united'):
        return -0.97
    if p.endswith('world'):
        return {'war': -1.05, 'health': -1.43, 'series': -1.23}.get(w, -0.0008)
    if p.endswith('national'):
        return {'geographic': -2.32, 'labor': -2.36, 'labour': -2.36}.get(w, -0.0008)
    if w == 'europe' and p.endswith(('eastern', 'western')):
        return -1.69
    if w == 'care' and p.endswith(('health', 'urgent')):
        return -1.59

    # Korean gi/ki plus grammatical endings of that syllable.
    if s in ('기', '기에', '기를', '기도', '기가', '기는', '기로', '기까지'):
        return -2.47
    if s == '대':
        return 4.11 if p.endswith('와') else 0.77
    # Japanese ki, including its Han spellings and common compounds.
    if s.startswith(('気', '氣')):
        return -3.61 if p.endswith('空') else -0.98
    if s == '機':
        return -2.16 if p.endswith('有') else -0.53
    if s == 'き':
        return -2.42 if p.endswith('ご') else -0.60
    if s == 'しく':
        return -1.20
    if s in ('く', 'くて'):
        return -0.30
    if s == '房':
        return 4.05 if p.endswith('書') else 0.49
    if s == '事' and p.endswith('工'):
        return 2.28
    if s == '大':
        return 0.29
    return -0.0008


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else b''
    before = history.decode('utf-8', errors='ignore')
    value = activation(prefix.token_strings[-1], before)
    history = (history + prefix.token_bytes[-1])[-240:]
    return (doc, history), value

"""Approximate a negative PRESS-family response, not general sentiment.

The table distinguishes stems and grammatical endings: depress/suppress/
repress are strong, express/compress weaker. Words can straddle tokens;
one following suffix can inherit part of the stem's response. Accents and
Cyrillic are transliterated. Nearby pres/prim/gress spellings and the Han
characters for suppression or melancholy have smaller additional rules.
Only 120 recent bytes and the previous stem response are remembered;
document boundaries reset them. Small background fluctuations are ignored.
"""
import regex as re
import unicodedata
from anyascii import anyascii

READS = ()
WORDS = re.compile(r"[^\W\d_]+")
CYRILLIC = re.compile(r"\p{Script=Cyrillic}")
# Columns: bare stem, action noun, past participle, adjective, -ing.
PRESS = {
    'depress': (-11.2, -8.1, -6.7, -6.5, -7.4),
    'suppress': (-8.3, -6.8, -5.8, -5.4, -6.7),
    'repress': (-10.8, -7.5, -8.0, -8.0, -7.0),
    'oppress': (-7.0, -5.4, -4.8, -4.4, -5.0),
    'impress': (-4.8, -1.3, -3.7, -1.4, -4.4),
    'decompress': (-3.8, -5.3, -2.0, -2.0, -2.0),
    'compress': (-2.1, -0.3, -0.9, -0.8, -1.0),
    'express': (-0.7, -0.6, -0.2, -0.3, -0.3),
    'press': (-1.5, -1.0, -2.3, -1.5, -1.7),
}


def normalize(word):
    word = word.lower()
    if word.isascii():
        return word
    word = ''.join(c for c in unicodedata.normalize('NFKD', word)
                   if not unicodedata.combining(c))
    return anyascii(word).lower()


def form(suffix):
    if not suffix:
        return 0
    if suffix in ('ion', 'ions', 'ione', 'iones', 'ionen'):
        return 1
    if suffix == 'ed':
        return 2
    if suffix in ('ive', 'ives', 'ively'):
        return 3
    if suffix == 'ing':
        return 4
    return 5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, last, last_word = b'', 0.0, ''
    else:
        _, tail, last, last_word = carry
    raw = prefix.token_bytes[-1]
    old = tail.decode('utf-8', 'ignore')
    text = (tail + raw).decode('utf-8', 'ignore')
    token = text[len(old):]
    prior = ''
    if token and token[0].isalpha():
        match = re.search(r'[^\W\d_]+$', old)
        if match:
            prior = match[0]
    value, spike, current_word = -0.001, 0.0, ''
    for match in WORDS.finditer(prior + token):
        if match.end() <= len(prior):
            continue
        original = match[0]
        word = normalize(original)
        cyrillic = bool(CYRILLIC.search(original))
        old_spelling = 'preff' in word
        word = word.replace('preff', 'press')
        before = max(0, len(prior) - match.start())
        # Transliteration is letter-preserving for the Latin/Cyrillic stems.
        before = len(normalize(match[0][:before]))
        current_word = word
        p = word.find('press')
        if p >= 0:
            stem, suffix = word[:p + 5], word[p + 5:]
            if before >= p + 5:
                if suffix in ('ion', 'ions', 'ed', 'es', 's', 'ing',
                              'ive', 'ives', 'ively', 'or', 'ors',
                              'ant', 'ants', 'ao'):
                    factor = 0.2 if stem.endswith('antidepress') else 0.62
                    value = min(value, factor * last)
                continue
            family = next((s for s in PRESS if stem.endswith(s)), 'press')
            f = form(suffix)
            v = PRESS[family][f] if f < 5 else 0.55 * PRESS[family][0]
            if stem.endswith('antidepress'):
                v = -4.7 if f == 0 else -3.3
            elif old_spelling:
                v = -4.8
            elif cyrillic and family == 'press':
                v = -5.0
            elif stem.endswith(('empress', 'vasopress')):
                v = -10.5 if stem.endswith('empress') else -13.0
            elif stem.endswith('espress'):
                v = -3.5
            elif before > 0 and family in ('depress', 'suppress', 'impress'):
                v -= 2.5
            elif before > 0 and family == 'express':
                v -= 1.0
            value, spike = min(value, v), min(spike, v)
        elif word.endswith(('imprim', 'reprim', 'supprim', 'deprim')):
            v = -11.0 if word.endswith('reprim') else -7.2
            value, spike = min(value, v), min(spike, v)
        elif word.endswith('pres'):
            v = -3.8 if cyrillic else -1.4
            if word.endswith('empres'):
                v = -8.0
            value, spike = min(value, v), min(spike, v)
        elif word.endswith('pre'):
            value = min(value, -0.5)
        elif word.endswith('pr'):
            v = -0.3
            if cyrillic and word.endswith(('depr', 'repr')):
                v = -6.5 if word.endswith('depr') else -4.5
            value = min(value, v)
        elif 'gress' in word:
            p = word.index('gress')
            stem, suffix = word[:p + 5], word[p + 5:]
            if stem.endswith('regress'):
                v = -2.3 if not suffix else -1.1
                value = min(value, 0.6 * last if before >= p + 5 else v)
            elif suffix.startswith('ion'):
                value = min(value, -0.5)
        elif before and last < -3.0 and last_word.endswith('imprim'):
            value = min(value, 0.25 * last)
    # The noun construction "suppression of" retains a smaller response.
    if token.lower().strip() == 'of' and last_word.endswith('suppression'):
        value = min(value, 0.45 * last)
    # Chinese/Japanese characters for suppression and melancholy.
    if token.strip() == '抑':
        value = min(value, -6.0)
    elif any(w in token for w in ('抑制', '抑郁', '抑鬱')):
        value = min(value, -2.6)
    if '郁' in token:
        value = min(value, -9.0 if old.endswith(('忧', '憂')) else -4.5)
    if '鬱' in token:
        value = min(value, -10.5)
    return (doc, (tail + raw)[-120:], spike, current_word), float(value)

"""A perfect-aspect detector, strongest on BEEN and HAD after HAVE.
Pronoun subjects and contractions strengthen it; modal HAVE weakens it.
The response sometimes persists onto a following state or progressive verb.
Small side rules cover Romance BEEN forms, UV spelling, the Thai long-i
vowel, and repeated middle dots. These are not a full account of all activity.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
AUX = {'have': 5.69, 'has': 5.58, 'had': 4.39, 'having': 4.5,
       "'ve": 7.69, "'s": 6.77, "'d": 5.06}
PERSON = {'i': 5.06, 'we': 3.27, 'you': 2.75, 'they': 1.44,
          'he': 2.44, 'she': 2.61, 'it': 0.57}
ADVERBS = {'not', 'never', 'ever', 'just', 'always', 'already', 'also',
           'still', 'yet', 'often', 'now', 'all', 'once', 'long', 'even'}
MODALS = {'to', 'would', 'could', 'should', 'may', 'might', 'must',
          'will', 'shall', 'can'}


def perfect_strength(text):
    text = text.lower().replace('’', "'")
    text = text.replace("can't", 'can not').replace("won't", 'will not')
    text = text.replace("n't", ' not')
    words = re.findall(r"'[a-z]+|[a-z]+", text)
    for i in range(len(words)-1, max(-1, len(words)-6), -1):
        word = words[i]
        if word in AUX:
            tail = words[i+1:]
            if any(w not in ADVERBS and w not in PERSON and
                   not w.endswith('ly') for w in tail):
                return 0.0
            subject = words[i-1] if i else ''
            if tail and tail[0] in PERSON:
                subject = tail[0]
            person = PERSON.get(subject, 0.0)
            strength = AUX[word] + person * (0.4 if word in {'had', "'d"} else 1.0)
            before = words[max(0, i-6):i]
            if word in {'have', "'ve"} and any(w in MODALS for w in before):
                strength *= 0.23
            if 'long' in tail:
                strength *= 0.45
            elif 'always' in tail:
                strength *= 0.62
            elif tail:
                strength *= 0.90
            return strength
    return 0.0


@lru_cache(maxsize=32768)
def verb_form(word):
    bases = wordnet.base_forms(word)
    verb = 'verb' in wordnet.parts_of_speech(word)
    if not verb:
        return ''
    if word.endswith('ing'):
        return 'progressive'
    if any(b != word for b in bases):
        return 'regular' if word.endswith('ed') else 'irregular'
    return ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, previous, last_value = '', '', 0.0
    else:
        _, history, previous, last_value = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    form = verb_form(word) if word.isascii() and word.isalpha() else ''
    needs_aux = word in {'been', 'had', 'seen', 'heard', 'known'} or form in {
        'regular', 'irregular'}
    strength = perfect_strength(history) if needs_aux else 0.0
    value = 0.0
    if word == 'been':
        value = -(strength or 3.0)
    elif strength:
        if word == 'had':
            value = -1.12 * strength
        elif word in {'seen', 'heard', 'known'}:
            value = -0.50 * strength
        elif form == 'regular':
            value = -0.07 * strength
        elif form == 'irregular':
            value = -0.05 * strength
    if previous == 'been':
        if word == 'known':
            value = 0.90 * last_value
        elif word in {'seen', 'heard'}:
            value = 0.35 * last_value
        elif form == 'progressive':
            # Mental states and generic activities carry a stronger trace.
            if word in {'looking', 'wanting', 'meaning', 'thinking'}:
                value = 0.65 * last_value
            elif word in {'working', 'doing', 'trying'}:
                value = 0.30 * last_value
            else:
                value = 0.10 * last_value
        elif word == 'around':
            value = 1.10 * last_value
        elif word in {'in', 'on', 'through', 'with', 'to'}:
            value = 0.36 * last_value
        elif word in {'a', 'an', 'the', 'so'}:
            value = 0.22 * last_value
    if previous == 'best' and word == 'known':
        value = -2.5
    if previous == 'after' and word in {'being', 'having'}:
        value = -3.1
    if token == ' été':
        value = -2.7
    elif word == 'sido':
        value = -2.8
    elif word == 'estado' and re.search(
            r'\b(?:ha|han|he|haber|había|haya)\s*$', history):
        value = -2.8
    elif word in {'stato', 'stata', 'stati', 'state'} and re.search(
            r'\b(?:è|era|sono|sia|essere)\s*$', history):
        value = -4.8
    # A separate spelling effect: UV, including a split between the letters.
    if token == 'uv':
        value = -10.8 if history.lower().endswith('ir') else -6.8
    elif token == 'UV':
        value = -3.5
    elif token in {'uve', 'uvo'}:
        value = -0.5 if history.lower().endswith('pre') else -6.0
    elif token == 'ув':
        value = -2.5
    elif token in {'v', 'w', 'в'} and history.lower().endswith(('u', 'у')):
        value = -5.0 if token == 'v' else -2.5
        if history.lower().endswith(('ou', 'au')):
            value = -1.5
    # Thai long-i vowel, especially after the consonant/carrier ท and อ.
    if token == 'ี':
        value = 9.0 if history.endswith(('ท', 'อ')) else 2.7
    if token == '··' and (not history or history.endswith('··')):
        value = 3.32
    return (doc, (history + token)[-120:], word, value), value

programs.haiku:
"""Component layers.1.mlp.down_proj:41: the perfect-participle detector.

Goes strongly negative on "been" (and "had") completing a present-perfect verb phrase:
"I've been", "has been", "have had". It is most negative after a first-person subject
("I've", "I have", "we have") and nearly off after a modal ("would have been").
"""
READS = ()
MODALS = {"would", "could", "should", "might", "may", "must", "will", "can"}
IVE = {"'ve", "’ve"}
HAVE = {"have", "has", "'ve", "’ve"}
FIRST = {"i", "we"}

def _word(prefix, back):
    i = len(prefix.token_ids) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip().lower()

def step(carry, prefix, upstream):
    word = _word(prefix, 0)
    prev, prev2 = _word(prefix, 1), _word(prefix, 2)
    if word == "been":
        window = [_word(prefix, k) for k in range(1, 7)]
        if any(w in MODALS for w in window[:3]):
            return carry, -1.0
        if prev in IVE:
            return carry, -11.0
        if prev in ("have", "has"):
            return carry, -10.0 if prev2 in FIRST else -6.0
        if prev in ("'s", "’s"):
            return carry, -7.5
        return carry, -5.5
    if word == "had" and prev in HAVE and prev2 not in MODALS:
        return carry, -8.0
    if word in ("seen", "heard", "known") and prev in HAVE:
        return carry, -3.0
    return carry, 0.0

programs.sol:
"""Sparse 'go/away' word detector, plus a negative document-start baseline.

Chinese 去 is strongest. Motion compounds are weaker; words about losing,
removing, or dying are weaker still. Thai ไป and Japanese 行く also respond.
These are lexical rules, not a general detector of motion in any language.
A subtraction/removal character immediately before standalone 去 damps it.
Earlier tokens containing 去 slightly discount later large responses.
Other tokens are near zero,
except for a broad negative response at the start of a new document.
"""
import regex

READS = ()

# Auxiliary + go; directional go; and longer go-related phrases.
GO_AUXILIARIES = {'再去', '不去', '要去', '想去', '而去', '望去'}
DIRECTIONAL_GO = {'过去', '過去', '下去', '出去', '进去', '回去', '走去'}
GO_PHRASES = {'一起去', '在过去', '过去的', '过去了', '走出去', '去过'}
LOSS_OR_REMOVAL = {'失去', '失去了', '除去', '去世'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, mentions = 0, 0
    else:
        position, mentions = carry[1] + 1, carry[2]
    word = prefix.token_strings[-1].strip()
    value = 0.0
    if word == '去':
        value = 8.0
        if position:
            previous = b''.join(prefix.token_bytes[-4:-1]).decode(
                'utf-8', errors='ignore')
            if previous.endswith(('减', '減', '消')):
                value = 1.5
            elif previous.endswith('抹'):
                value = 3.5
    elif word in GO_AUXILIARIES or word == '上去':
        value = 6.0
    elif word in DIRECTIONAL_GO or word in {'去了', '我去', '去做', '去看'}:
        value = 4.0
    elif word == '去年' or word in GO_PHRASES or word == '死去':
        value = 2.0
    elif word in {'看上去', '去找', '去买', '离去', '去哪里'}:
        value = 1.0
    elif word in LOSS_OR_REMOVAL:
        value = 0.4
    elif word == 'ไป':
        value = 3.0
    elif word == '行く':
        value = 1.0
    elif word in {'起来', '起來', '看起來'}:
        value = 0.6

    if value >= 2.0 and '去' in word:
        value -= 0.4 * min(mentions, 2)
        if position == 0:
            value *= 0.65
    elif position == 0 and value == 0.0:
        if word.startswith('<|'):
            value = -0.05
        elif word.isdigit():
            value = -0.59
        elif word.isascii() and word.isalpha():
            value = -0.45
        elif regex.search(r'\p{Script=Hiragana}|\p{Script=Katakana}', word):
            value = 0.0
        else:
            value = -0.33
    mentions += int('去' in word)
    return (doc, position, mentions), value

"""A spelling detector for MC and MAC, especially short name prefixes.

It recognizes the cluster inside a token or across a token boundary.  Short
Mc-/Mac- prefixes, abbreviations and code identifiers respond more strongly
than complete names.  Other short 'ac' fragments give a negative contrast.
Selected Greek, Arabic and Cyrillic spellings extend the same pattern.
Document starts amplify positives; joined bytes recognize split characters.
Everything else is predicted as zero, leaving background variation unexplained.
"""
import re
from anyascii import anyascii

READS = ()


def response(token, previous):
    word = token.strip().lstrip('_/.(>-')
    low = word.lower()
    boundary = token != word

    if low in ('mc', 'mac', 'mack', 'mcc'):
        if low in ('mack', 'mcc'):
            return 5.8 if low == 'mack' else 4.8
        if word.isupper():
            return (2.7 if boundary else 4.8) if low == 'mc' else 3.6
        if low == 'mc':
            return 6.6 if word.startswith('M') else 5.1
        return 5.1 if word.startswith('M') else (4.0 if boundary else 6.1)

    # Unfinished Scottish name prefixes versus names already in one token.
    if re.fullmatch(r'Mc[A-Za-z]+', word):
        if len(word) <= 5:
            return 4.8 + 3.0 * ('M' in word[2:])
        return 1.4
    if low in ('macbook', 'macos'):
        return 2.7
    if word.startswith('Mac') and not low.startswith(('mach', 'macro')):
        return 1.0

    # Short abbreviations such as BMC, and identifiers such as hmac/mcmc.
    if len(word) <= 4 and re.fullmatch(r'[a-z]*ma?c', low):
        return 6.5
    if word.isupper() and 'MC' in word and len(word) <= 4:
        return 4.0

    if token and not token[0].isspace():
        # Dotted initials count, but the dot in a URL or filename does not.
        dotted = token.startswith('.') and previous.endswith('.M')
        fragment = token[1:] if dotted else token
        stem = previous.strip().lstrip('._/(-')
        if (len(stem) <= 4 and len(fragment) <= 5
                and re.match(r'(?i)a?c', fragment)
                and not re.match(r'(?i)a?c[ahouy]|acro', fragment)
                and (fragment.islower() or fragment.isupper())):
            if previous.endswith(('m', 'M', 'ma', 'Ma')):
                if fragment.lower() in ('c', 'ac'):
                    if previous.endswith('M') and fragment.islower():
                        return 10.8
                    return 7.0
                if len(fragment) <= 2:
                    return 5.0
                return 3.8 if len(fragment) < 5 else 1.5

        if token == 'ac' and previous[-1:].isalpha():
            last = previous[-1:].lower()
            return -2.0 if last in 're' else (-1.0 if last in 'hf' else -0.4)

        # K-like letters in the scripts where the pattern transfers well.
        if token in ('ك', 'ک', 'چ', 'κ') or token.startswith('ак'):
            left = anyascii(previous).lower()
            if re.search(r'ma?$', left):
                return 3.0 if token == 'چ' else 5.5
        if word in ('Мак', 'мак'):
            return 5.0

    # Chinese wheat/surname characters, used to transcribe Mac-/Mc- names.
    if word in ('麦', '麥'):
        return 7.5
    if word in ('麦克', '麥克'):
        return 4.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous = '' if reset else carry[1]
    tail = b'' if reset else carry[2]
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    value = response(token, previous)
    if reset and value > 0:
        value *= 1.8
    # Decode characters completed by the newest bytes, not replacement glyphs.
    if '\ufffd' in token:
        text = (tail + raw).decode('utf-8', errors='replace')
        if text.endswith(('麦', '麥')):
            value = 11.0
        elif text.endswith('맥'):
            value = 9.0
    return (doc, token, (tail + raw)[-6:]), value

"""Approximate a negative detector of short written ar-syllables.

The largest responses are to arm, art/arts and arch spellings.  A leading
word boundary makes these much stronger than the same letters inside a word.
Short continuations can finish the syllable or an inflection.  Transliteration
makes the same rules usable for accented Latin and Cyrillic text.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=20000)
def spelling(text):
    return anyascii(text)


def onset(s):
    if s == 'ar':
        return 2.0
    if s in (
        'arm', 'arms', 'armed', 'arb', 'arbe', 'arbit', 'ard', 'ark', 'arch'
    ):
        return 3.5
    if s in ('arts', 'arte'):
        return 3.4
    if s == 'art':
        return 1.55
    if s == 'arg':
        return 1.7
    if s in ('arn', 'arc'):
        return .8
    if s.startswith('arbitr'):
        return 1.0
    if s.startswith('arm'):
        return .7
    if s.startswith('ar') and len(s) > 2 and s[2] not in 'aeioury':
        return .25
    if s == 'arrow':
        return .6
    if s == 'air':
        return .3
    return 0.0


def predict(text, oldword):
    text = spelling(text)
    match = re.search('[A-Za-z]+', text)
    if not match:
        return 0.0, ''
    s = match[0].lower()
    joins = match.start() == 0 and bool(oldword)
    title = match[0][0].isupper() and not match[0].isupper()
    boundary = not joins or title
    value = -onset(s) * (1.0 if boundary else .03)
    # Proper-name/code Or, not the ordinary conjunction 'or'.
    if s == 'or' and (title or text.startswith('/')):
        value = -.65
    # Finish a spelling split across token boundaries.
    if joins:
        if oldword in ('a', 'o') and s.startswith('r'):
            value = -onset(oldword + s) * 1.7
            if s == 'r':
                value = -7.0 if oldword == 'a' else -3.0
        elif oldword.endswith('ar') and s[0] not in 'aeiourxy':
            value = -(3.2 if len(s) <= 4 else .7)
            if oldword != 'ar':
                value = -.2 if len(s) <= 4 else 0.0
        elif oldword in ('art', 'arm', 'arch'):
            if s in ('s', 'es', 'e', 'i', 'ed'):
                value = -4.7
            elif len(s) <= 4:
                value = -.8
    word = (oldword + s) if joins else s
    if title and onset(s):
        word = s
    if match.end() != len(text):
        tail = re.search('[A-Za-z]+$', text)
        word = tail[0].lower() if tail else ''
    return value, word[-24:]


def step(carry, prefix, upstream):
    # Track only the trailing word, resetting at document boundaries.
    doc = prefix.document_ids[-1]
    oldword = carry[1] if carry is not None and carry[0] == doc else ''
    value, word = predict(prefix.token_strings[-1], oldword)
    return (doc, word), value

"""Predict punctuation boundaries and German clause-opening forms.

Detached or repeated stops are negative; leading-space stops are milder.
Dotted leaders stay quiet unless they follow a different sentence stop.
Commas after English coordinators are negative. German der/die-type forms
at comma, semicolon, or dash boundaries are positive when recent text has
German function words. Small bracket/operator responses are approximated
coarsely; other token-specific variation is ignored. The 256-character
trailing window resets at document boundaries.
"""
import re
import unicodedata

READS = ()
GERMAN_WORDS = re.compile(
    r'\b(?:und|der|die|das|ist|ein|eine|nicht|mit|auf|für|von|zu|auch|es|'
    r'gibt|sich|sind|wird|werden|im|als|den|dem)\b',
    re.IGNORECASE,
)
RELATIVES = {'der': 3.2, 'die': 3.4, 'das': 2.4,
             'den': 1.1, 'dem': 0.7, 'deren': 0.5, 'dessen': 0.5}
STOPS = ('.', ',', ':', ';', '?', '!')
COORDINATORS = re.compile(r'\b(and|but|or|so)\Z', re.IGNORECASE)
QUOTES = '\"\'”’»'


def canonical(c):
    if c in ('。', '…'):
        return '.'
    c = unicodedata.normalize('NFKC', c)
    return {'。': '.', '、': ','}.get(c, c)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, previous = ('', '')
    if carry is not None and carry[0] == doc:
        tail, previous = carry[1:]
    token = prefix.token_strings[-1]
    stripped = token.lstrip()
    first = canonical(stripped[:1])
    last = canonical(tail[-1:])
    leading = len(stripped) != len(token)
    boundary = bool(tail) and (tail[-1].isspace()
                               or tail.endswith(('\\n', '\\r', '\\t')))
    unquoted = tail.rstrip(QUOTES)
    duplicated = bool(unquoted) and canonical(unquoted[-1:]) in STOPS
    value = 0.0

    word = stripped
    if (leading and word in RELATIVES and tail.rstrip().endswith((',', ';', '—'))
            and GERMAN_WORDS.search(tail)):
        value = RELATIVES[word]
    elif first in STOPS:
        if stripped.startswith(('..', '…')):
            # Dotted leaders are quiet; mixed stops such as ?... are not.
            value = -2.5 if duplicated and last != '.' else -0.15
        elif leading:
            if duplicated and first in ('.', ',', ':', ';'):
                value = {'.': -1.3, ',': -1.7, ':': -1.8, ';': -2.3}[first]
                if first == '.' and previous.endswith(' .'):
                    value = -0.25  # Spaced ellipses: . . .
            else:
                value = {'.': -0.65, ',': -0.55, ':': -0.18,
                         ';': -0.6, '?': -0.25, '!': 0.0}[first]
        elif boundary:
            if first == '.' and any(ch.isalpha() for ch in stripped):
                value = -3.8  # Leading-dot names, such as hidden files.
            else:
                value = -0.3 if first == '!' else -1.8
        elif duplicated:
            value = -2.8
            if first == ',':
                value = -2.2
            elif first == '!' and last == '!':
                value = -1.3
        elif last and last in QUOTES and first in ('.', ';'):
            value = -1.2
        elif first == ',':
            conjunction = COORDINATORS.search(tail)
            if conjunction:
                word = conjunction.group(1).lower()
                value = {'and': -1.85, 'but': -2.35,
                         'or': -0.6, 'so': -0.65}[word]
    elif first in (')', ']') and (leading or boundary):
        value = -0.3
    elif first in ('=', '+', '/') and boundary and not leading:
        value = -0.3
    return (doc, (tail + token)[-256:], token), value

programs.haiku:
"""layers.1.mlp.down_proj:45 as a short rule program.

What the component does, in plain terms: it is mostly quiet, but it reacts to
punctuation and a few words in unusual places.

- Strongly negative on the git directory names ".git" and ".github" (file listings).
- Positive on the German relative pronouns die / der / das / den / dem when they come
  straight after a comma (", die" opening a relative clause, as in "Grüße an die, die ...").
- Negative on punctuation placed oddly: a comma right after a conjunction ("and,", "So,",
  "But,"), a space-separated period, comma, parenthesis or colon (" .", " ,", " )", " :"),
  punctuation directly after other punctuation, and punctuation as the first token of a
  document.
- Zero everywhere else: ordinary words and ordinary commas, periods and newlines sit near 0.

The values are the typical sizes seen in a sample of training text. The program does not
reproduce the many small context effects, so it explains only part of the variance.
"""

READS = ()

GIT_DIRECTORIES = {".git", ".github"}
GERMAN_RELATIVE_PRONOUNS = {" die", " der", " das", " den", " dem"}
CONJUNCTIONS = {" and", "and", " And", "And", " But", "But", " So", "So", " Then", "Then", " or"}
SPACED_PUNCTUATION = {" .": -0.9, " ,": -0.6, " )": -0.4, " :": -0.25}


def is_punctuation(text):
    """True for a token made only of punctuation or symbols, such as ',' or '.\\n'."""
    return len(text) > 0 and all(not c.isalnum() and not c.isspace() for c in text)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix) > 1 else ""
    first_in_document = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]

    if first_in_document:
        return None, -0.6 if is_punctuation(token) else 0.0
    if token in GIT_DIRECTORIES:
        return None, -4.5
    if token in GERMAN_RELATIVE_PRONOUNS and previous == ",":
        return None, 2.5
    if is_punctuation(token) and previous in CONJUNCTIONS:
        return None, -1.5
    if token in SPACED_PUNCTUATION:
        return None, SPACED_PUNCTUATION[token]
    if is_punctuation(token) and is_punctuation(previous):
        return None, -0.12
    return None, 0.0

programs.sol:
"""Detect unfinished UTF-8 characters and a few conspicuous text markers.

The largest rule recognizes the colon of a document-opening 'Title:'.
Smaller rules recognize unfinished UTF-8 characters: middle bytes respond
more than leading bytes, and space-prefixed fragments usually respond less.
Code fences, combining marks and a few symbols also respond. Ordinary text
is nearly zero. These are coarse averages, not token-specific predictions.
State resets at each document boundary.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, needed = 0, '', 0
    else:
        _, position, previous, needed = carry
    text = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    for byte in raw:
        if byte < 128:
            needed = 0
        elif byte >= 240:
            needed = 3
        elif byte >= 224:
            needed = 2
        elif byte >= 192:
            needed = 1
        else:
            needed = max(0, needed - 1)

    value = 0.001
    continuation = raw and all(128 <= b < 192 for b in raw)
    if needed == 1:
        if raw.startswith(b' '):
            value = 0.11 if len(raw) == 2 else 0.22
            if len(raw) == 3:
                hint = (raw[1:] + b'\x80').decode('utf8', 'replace')
                if len(hint) == 1 and 'HANGUL' in unicodedata.name(hint, ''):
                    value = 0.65
        elif continuation:
            value = 1.04
        elif len(raw) == 1:
            value = 0.48
        else:
            value = 0.60 if len(raw) == 2 else 0.15
    elif needed > 1:
        value = 0.11
    elif continuation:
        value = 0.06
    clean = text.strip()
    if clean and set(clean) == {'`'} and len(clean) >= 2:
        if previous.endswith(('\n\n', ':\n', '：\n')):
            value = 0.58
        else:
            value = 0.21 if len(clean) == 2 else 0.25
    if clean and all(unicodedata.category(c).startswith('M') for c in clean):
        value = 0.85 if 'ARABIC' in unicodedata.name(clean[0], '') else 0.3
    if clean == 'っ':  # Japanese small tsu: consonant doubling.
        value = 0.74
    if clean == '©':
        value = 0.95
    if clean in {'✓', '✔', '☑'}:
        value = 0.28
    if clean == '··':
        value = 1.86
    if text == '\x00':
        value = 0.33
    if position == 0 and text == 'Title':
        value = 0.44
    if position == 1 and previous == 'Title' and text == ':':
        value = 16.94
    return (doc, position + 1, text, needed), value

programs.haiku:
"""Layer-1 MLP feature 48: Sino-Japanese / Sino-Korean kanji words, and the Chinese 上.

What the program predicts (every other position predicts 0):
  * A Han character or Hangul syllable inside Japanese or Korean text (a kana or Hangul
    character within the last 16 tokens) pushes the activation negative. The push is -4 for
    a short list of very common Sino-words (上, 間, 問題, 想, 以上, 段, 可能, 象, 상, 準 ...),
    -1.5 for a second list of frequent kanji nouns (場, 質, 状, 結果, 時間 ...), and 0 for
    other characters.
  * 上 in Chinese text (no kana or Hangul nearby) is the sign flip. When an abstract cue
    word such as 在, 客观, 名义, 程度 comes just before it, so that 上 means "in terms of"
    (在感情上, 客观上, 在某种程度上), it is +2. Otherwise 0.
  * Chinese aspect words 方面, 上的, 实际上 are mildly positive.
  * The colon in a document header "<|endoftext|>Title:" is strongly positive (+7.2).

The magnitudes are rough averages of the component's activation on training rows, not fitted
per token. Most of its variance is on rare large spikes; the lists name the biggest ones.
"""

READS = ()

STRONG = {
    "上", "間", "問題", "想", "以上", "段", "可能", "象", "상", "準", "通常", "像", "賞", "響", "舞台",
}
MEDIUM = {
    "장", "場", "質", "講", "状", "結果", "丈夫", "影響", "印象", "問", "現在", "題", "重要",
    "空間", "門", "時間", "装", "操作", "張", "面", "果", "富", "記", "商品", "係", "常", "側",
}
ASPECT = {"方面": 1.2, "上的": 2.0, "实际上": 0.8, "等方面": 0.9, "面": 0.7}
ABSTRACT_CUE = set("在从客观名义程度视觉感情数学管理理论角度意义方面本质事实基本")


def is_han(s):
    return len(s) > 0 and all("一" <= c <= "鿿" or "㐀" <= c <= "䶿" for c in s)


def is_hangul(s):
    return len(s) > 0 and all("가" <= c <= "힯" for c in s)


def is_kana(s):
    return any("぀" <= c <= "ヿ" for c in s)


def step(carry, prefix, upstream):
    strs = prefix.token_strings
    tok = strs[-1]
    japanese_or_korean = any(is_kana(s) or is_hangul(s) for s in strs[-16:])

    if tok == ":" and len(strs) >= 3 and strs[-2] == "Title" and strs[-3] == "<|endoftext|>":
        return None, 7.2
    if tok == "上" and not japanese_or_korean:
        cue = any(s in ABSTRACT_CUE for s in strs[-5:-1])
        return None, 2.0 if cue else 0.0
    if (is_han(tok) or is_hangul(tok)) and japanese_or_korean:
        if tok in STRONG:
            return None, -4.0
        if tok in MEDIUM:
            return None, -1.5
        return None, 0.0
    if not japanese_or_korean and tok in ASPECT:
        return None, ASPECT[tok]
    return None, 0.0

