"""A sparse approximation, especially of triggering/promoting and action measures.

Also recognize GitHub domain completions, a few causal-agent noun endings,
and negative responses to 'Chris' and internal '-chia'/'-chis' endings.
Nearby qualifiers separate action 'measures' from quantity measurements.
These rules keep repeatable word/spelling patterns instead of memorizing
all token-specific responses. Unmodelled tokens receive zero; context is a
short, document-local byte tail.
"""
READS = ()

ACTION_MEASURES = {
    'appropriate', 'necessary', 'reasonable', 'emergency', 'control',
    'defensive', 'corrective', 'active', 'austerity', 'other', 'new',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b''
    current = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    before = tail.decode('utf-8', errors='replace').lower()
    previous = before.split()[-1] if before.split() else ''
    value = 0.0
    if word == '.com' and before.endswith('github'):
        value = 1.65
    elif word == 'measures':
        if previous in ('security', 'safety', 'protective', 'preventive'):
            value = 2.3
        elif previous in ACTION_MEASURES:
            value = 1.4
    elif word == 'trigger':
        value = 1.15 if token.startswith(' ') or token[0].isupper() else 0.35
    elif word in ('triggered', 'triggers'):
        value = 0.6
    elif word == 'triggering':
        value = 0.3
    elif word in ('measure', 'measured', 'measuring', 'measurement', 'measurements'):
        value = -0.12
    elif word in ('ator', 'ators'):
        if before.endswith('acceler'):
            value = 4.4
        elif before.endswith('activ'):
            value = 1.9
        elif before.endswith('orchestr'):
            value = 1.7
        elif before.endswith('cre'):
            value = 2.8
        elif before.endswith('concentr'):
            value = 1.2
    elif word == 'ia' and before.endswith('ch'):
        value = -4.6 if before.endswith('escherich') else -2.7
        if before.endswith('zech'):
            value = -1.0
    elif word == 'chris':
        value = -0.9
    elif token == 'is' and before.endswith('ch'):
        value = -1.0

    # Characters/words for causing, urging, implementing, and taking measures.
    if token == '措':
        value = 5.1
    elif token in ('触', '觸'):
        value = 4.0
    elif token in ('促', '惹'):
        value = 3.2
    elif token == '措施':
        value = 2.9
    elif token in ('促进', '促進', '促使'):
        value = 2.4
    elif token == '施':
        value = 0.6
    elif token == '手' and before.endswith(('触', '觸')):
        value = 5.0
    # The same characters may be split across UTF-8 tokens.
    elif '\ufffd' in token:
        joined = (tail[-6:] + current).decode('utf-8', errors='replace')
        if joined.endswith(('触', '觸', '措')):
            value = 6.4
    return (doc, (tail + current)[-64:]), value

"""End-of-document markers and a few Unix directory segments.

The marker gets a large positive response, slightly smaller after mainly
Han-script text. Paths give a second positive response, strongest for
workspace, opt and local. Relative tmp paths and shebangs are weaker.
Other, mostly small and token-specific, responses are left at zero.
"""
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
