from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
SINGULAR_ENDINGS = (
    'are', 'ere', 'ire', 'ore', 'ale', 'ile', 'ente', 'ione', 'mente',
    'ice', 'one', 'ese',
)
PLURAL_ENDINGS = ('ie', 'che', 'ghe', 'ze', 'ure')
FUSED_PREPOSITIONS = {'delle', 'nelle', 'sulle', 'dalle', 'alle', 'colle'}


def clip(x):
    return max(0.0, min(1.0, x))


@lru_cache(maxsize=60000)
def word_frequencies(word):
    word = word.lower()
    if (len(word) < 2 or len(word) > 50
            or any(c not in 'abcdefghijklmnopqrstuvwxyzàèéìòù' for c in word)):
        return (0.0,) * 6
    return tuple(zipf_frequency(word, lang)
                 for lang in ('it', 'en', 'fr', 'es', 'pt', 'de'))


@lru_cache(maxsize=30000)
def plural_likelihood(word):
    if word.endswith(('arle', 'erle', 'irle')):
        return 1.0  # An infinitive followed by the feminine pronoun -le.
    singular = word[:-1] + 'a'
    if word.endswith(('che', 'ghe')):
        singular = word[:-2] + 'a'
    sf = zipf_frequency(singular, 'it')
    pf = word_frequencies(word)[0]
    return clip((sf - 2) / 2) * clip((sf - pf + 1.5) / 2)


