"""Activation of layers.1.mlp.down_proj:59, a component that reacts to the start of a document.

Read in plain terms: it is silent almost everywhere. Its one strong behaviour is on the first
token of a document (the token right after <|endoftext|>, or the first token of a row). Its
value there depends on what that opening token is:
  - an opening letter or digit with no leading space ("P", "n", "4") is strongly negative;
  - a bare word fragment such as " of", " in", " for" is negative;
  - an opening punctuation mark with no leading space ("#", ".", ",", "%") is positive.
Separately, a digit "1" right after a digit "1" or "2" (as in "11" or "21") is mildly positive.
Everything else is predicted as 0.
"""

READS: tuple[str, ...] = ()

MIDSENTENCE_WORDS = {" of", " in", " for"}


def _document_start(prefix) -> bool:
    if prefix.position == 0:
        return True
    return prefix.document_ids[-1] != prefix.document_ids[-2]


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if _document_start(prefix):
        if len(token) == 1 and token.isalnum() and token.isascii():
            return carry, -0.45
        if token in MIDSENTENCE_WORDS:
            return carry, -0.4
        if len(token) == 1 and not token.isspace() and token.isascii():
            return carry, 0.2
        return carry, 0.0
    if token == "1" and prefix.token_strings[-2] in ("1", "2"):
        return carry, 0.27
    return carry, 0.0

"""Activation predictor for MLP component layers.1.mlp.down_proj:60 (Qwen3-1.7B, layer 1).

What the component does, in plain terms
---------------------------------------
It is a comma detector. Almost every token leaves it at about zero; on a comma
it switches on, and how strongly depends on the word just before the comma:

- a comma right after a clause opener ("and,", "or,", "which,", "who,", "because,",
  "if,", "when,") is the strongest case: the sentence is about to take an aside
  or a new clause;
- after a modal ("may,", "should,") it is strong; after a verb of being, having or
  saying ("is,", "has,", "said,") it is moderate;
- after "that", a conjunction-like adverb ("but,", "so,", "now,") or a preposition
  it is moderate; after a pronoun or a plain adverb ("however,", "therefore,") weak;
- after an ordinary word (a noun in a list, a name, a number) it is near zero;
- in code (a line with brackets, operators or identifiers such as `def`, `int`,
  `self`) the comma is slightly negative, as in parameter lists.

The numbers are the mean activations of each group on 2048 training rows, so the
program predicts the average size of the comma's contribution. Every other token is
predicted as 0. On held-out rows this explains about a fifth of the variance (the
word groups alone give most of it); the rest is spread over many words and contexts
that a short word list cannot capture.
"""

READS = ()

CLAUSE_OPENERS = {"and", "or", "because", "which", "who", "whom", "whose", "when", "if",
                  "where", "since"}
MID_CONNECTIVES = {"but", "as", "while", "though", "although", "whereas", "so", "then",
                   "now", "than"}
MODALS = {"may", "can", "could", "would", "should", "might", "must", "will", "shall"}
BE_HAVE_SAY = {"is", "are", "was", "were", "be", "been", "has", "have", "had", "said",
               "say", "says", "means", "mean", "think", "believe", "know"}
ADVERBS = {"therefore", "thus", "hence", "indeed", "instead", "however", "actually",
           "here", "there", "today", "again", "also", "still"}
PREPOSITIONS = {"of", "to", "for", "at", "with", "by", "from", "in", "on", "into", "about",
                "under", "during", "after", "before"}
PRONOUNS = {"me", "you", "him", "them", "it", "us", "this", "these", "those", "she", "he",
            "i", "we", "they"}
CODE_WORDS = {"def", "int", "void", "import", "const", "string", "public", "function",
              "return", "self", "None", "True", "False", "var", "class"}
CODE_MARKS = "(){}[];=<>_"

VALUE = {"clause": 5.0, "mid": 1.8, "modal": 3.2, "be_have_say": 1.3, "that": 1.8,
         "adverb": 0.5, "prep": 0.9, "pronoun": 0.5, "other": 0.16}
CODE_VALUE = -0.06
WINDOW = 12


def group_of(word):
    if word in CLAUSE_OPENERS:
        return "clause"
    if word in MID_CONNECTIVES:
        return "mid"
    if word in MODALS:
        return "modal"
    if word in BE_HAVE_SAY:
        return "be_have_say"
    if word == "that":
        return "that"
    if word in ADVERBS:
        return "adverb"
    if word in PREPOSITIONS:
        return "prep"
    if word in PRONOUNS:
        return "pronoun"
    return "other"


def looks_like_code(recent):
    """True when at least 10% of the last few tokens are code-like."""
    if not recent:
        return False
    hits = sum(1 for s in recent if any(c in s for c in CODE_MARKS) or s.strip() in CODE_WORDS)
    return hits >= 0.1 * len(recent)


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] != ",":
        return None, 0.0
    word = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    group = group_of(word.lower())
    if group == "other" and looks_like_code(prefix.token_strings[-WINDOW - 1:-1]):
        return None, CODE_VALUE
    return None, VALUE[group]

