                 "has": -3.0, "can": -1.0, "could": -1.0, "would": -0.5}
OTHER_LANGUAGE_HOW = {"wie": -2.0, "como": -0.8, "как": -0.9}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if prev == "how" and word in AUX_AFTER_HOW:
        return carry, AUX_AFTER_HOW[word]
